        "afterLabel": {
          "$state": "/input/afterLabel"
        },
        "reveal": {
          "$bindState": "/reveal"
        },
        "notes": {
          "$bindState": "/notes"
        },
        "submit": {
          "id": "comparison_notes",
          "label": "Send comparison notes"
        }
      }
    }
  }
}

{
  "id": "voyager.clip-review",
  "version": 1,
  "title": "Review the clips",
  "description": "Review a batch of presented clips one after another: keep, refine with a note, or drop each, and send the verdicts together.",
  "tags": ["review", "media", "batch", "motion"],
  "renderer": "spec",
  "entrypoint": "spec.json",
  "inputSchema": {
    "type": "object",
    "properties": {
      "clips": {
        "type": "array",
        "minItems": 1,
        "maxItems": 60,
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string"
            },
            "number": {
              "type": "integer"
            },
            "title": {
              "type": "string"
            },
            "assetRef": {
              "type": "string"
            }
          },
          "required": ["id", "number", "title", "assetRef"],
          "additionalProperties": false
        }
      }
    },
    "required": ["clips"],
    "additionalProperties": false
  },
  "actions": [
    {
      "id": "review_clips",
      "label": "Send review",
      "inputSchema": {
        "type": "object",
        "properties": {
          "reviews": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string"
                },
                "number": {
                  "type": "integer"
                },
                "title": {
                  "type": "string"
                },
                "verdict": {
                  "type": "string",
                  "enum": ["keep", "refine", "drop"]
                },
                "note": {
                  "type": "string"
                }
              },
              "required": ["id", "number", "title", "verdict", "note"],
              "additionalProperties": false
            }
          },
          "unreviewed": {
            "type": "array",
            "items": {
              "type": "integer"
            }
          }
        },
        "required": ["reviews", "unreviewed"],
        "additionalProperties": false
      },
      "delivery": {
        "kind": "agent"
      },
      "cardinality": "repeatable"
    }
  ],
  "bindings": [],
  "exampleInputs": {
    "clips": [
      {
        "id": "clip-1",
        "number": 1,
        "title": "Logo reveal, ink bleed",
        "assetRef": "PRESENTED_FILE_ID_1"
      },
      {
        "id": "clip-2",
        "number": 2,
        "title": "Logo reveal, glyph cascade",
        "assetRef": "PRESENTED_FILE_ID_2"
      }
    ]
  },
  "fallback": "Review the clips by number in the conversation: say keep, refine or drop for each, with a note on what to change."
}

{
  "state": {
    "reviews": {}
  },
  "root": "card",
  "elements": {
    "card": {
      "type": "Card",
      "props": {
        "title": "Review the clips",
        "description": "Keep, refine or drop each clip. Refine asks what should change. K, R and D choose too."
      },
      "children": ["review"]
    },
    "review": {
      "type": "ClipReview",
      "props": {
        "clips": {
          "$state": "/input/clips"
        },
        "value": {
          "$bindState": "/reviews"
        },
        "submit": {
          "id": "review_clips",
          "label": "Send review"
        }
      }
    }
  }
}

