      "message": {
        "type": "string"
      },
      "format": {
        "type": "string"
      },
      "duration": {
        "type": "number"
      }
    },
    "required": [],
    "additionalProperties": false
  },
  "actions": [
    {
      "id": "use_brief",
      "label": "Use this brief",
      "inputSchema": {
        "type": "object",
        "properties": {
          "audience": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "format": {
            "type": "string"
          },
          "duration": {
            "type": "number"
          }
