{
  "state": {
    "audience": {
      "$state": "/input/audience",
      "fallback": ""
    },
    "message": {
      "$state": "/input/message",
      "fallback": ""
    },
    "format": {
      "$state": "/input/format",
      "fallback": "16:9"
    },
    "duration": {
      "$state": "/input/duration",
      "fallback": 0
    }
  },
  "root": "card",
  "elements": {
    "card": {
      "type": "Card",
      "props": {
        "title": "Shape the brief"
      },
      "children": ["audience", "message", "format", "duration", "use"]
    },
    "audience": {
      "type": "TextField",
      "props": {
        "label": "Audience",
        "value": {
          "$bindState": "/audience"
        }
      }
    },
    "message": {
      "type": "TextArea",
      "props": {
        "label": "Main message",
        "value": {
          "$bindState": "/message"
        },
        "rows": 3
      }
    },
    "format": {
      "type": "Select",
      "props": {
        "label": "Format",
        "options": [
          {
            "value": "16:9",
            "label": "16:9"
          },
          {
            "value": "9:16",
            "label": "9:16"
          },
          {
            "value": "1:1",
            "label": "1:1"
          },
          {
            "value": "Other",
            "label": "Other"
          }
        ],
        "value": {
          "$bindState": "/format"
        }
      }
    },
    "duration": {
      "type": "NumberField",
      "props": {
        "label": "Duration in seconds",
        "min": 1,
        "value": {
          "$bindState": "/duration"
        }
      }
    },
    "use": {
      "type": "Button",
      "props": {
        "label": "Use this brief",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "use_brief",
          "params": {
            "audience": {
              "$state": "/audience"
            },
            "message": {
              "$state": "/message"
            },
            "format": {
              "$state": "/format"
            },
            "duration": {
              "$state": "/duration"
            }
          }
        }
      }
    }
  }
}

// A story piece's approval as the agent applies it (FILM_PIECE_NOTE in catalog.ts): the agent
// does not show an approved piece again, so its card shows itself approved (ENG-7202).

// A receipt the host keeps the widget open for leaves it in review (receiptFolds in
// WidgetCollapsibleBody.tsx).
const KEEPS_OPEN = ["held", "failed", "cancelled", "destination_required", "outcome_unknown"];

function folds(receipt) {
  return typeof receipt?.status === "string" && !KEEPS_OPEN.includes(receipt.status);
}

// The shown alternative's items with the edits applied and the dropped ones gone. A revise (one
// with nothing to redo approves), an edit or a drop bumps the version by one; a pick alone does
// not. Should the file end up otherwise, Reopen at this version is refused and the agent shows the
// piece from the file. None for an approval that adds items: the agent places, numbers and times
// them, so it shows that piece again.
function approvedPiece(piece, decision, picked, added, decisionOf, items) {
  if (added.length) return undefined;
  let bump = decision === "revise";
  const kept = items.flatMap((item) => {
    const { drop, edits } = decisionOf(item);
    if (drop || Object.keys(edits).length) bump = true;
    return drop ? [] : [{ ...item, fields: { ...item.fields, ...edits } }];
  });
  const chosen = picked ?? piece.chosenAlternative;
  const same = !bump && chosen === piece.chosenAlternative;
  return {
    version: piece.version + (bump ? 1 : 0),
    chosenAlternative: chosen,
    summary: same ? piece.summary : undefined,
    items: kept,
    status: "approved",
  };
}

// Kept in the widget's state, which every client of it reads (a draft is one client's), so
// another window or device shows the piece approved too. A failed write leaves the card in
// review there; approving it again changes nothing and the agent shows the piece from the file.
// null takes it back.
async function keepApproval(host, approved) {
  try {
    const { revision } = await host.state.read();
    await host.state.patch({ expectedRevision: revision, patch: { approved } });
  } catch {}
}

// Sends an approval, kept first: once it is accepted the host folds the card, and a folded card's
// writes can be lost. Taken back when it is not accepted.
async function sendKeeping(host, approval, from, send) {
  if (!approval) return send();
  await keepApproval(host, { from, piece: approval });
  const receipt = await send().catch(async (error) => {
    await keepApproval(host, null);
    throw error;
  });
  if (!folds(receipt)) await keepApproval(host, null);
  return receipt;
}

globalThis.filmPieceApproval = { approvedPiece, folds, sendKeeping };

{
  "id": "voyager.film-piece",
  "version": 1,
  "title": "Review a film card",
  "description": "Review one card of a film before generation (a story piece, the treatment, breakdown, shot list, look development, previs or keyframes): pick an alternative, keep, edit, redo, drop or reopen each item, add items of your own to a story piece, then send revisions or approve the card.",
  "tags": ["review", "film", "story", "approval"],
  "entrypoint": "index.html",
  "inputSchema": {
    "type": "object",
    "properties": {
      "piece": {
        "oneOf": [
          {
            "$ref": "#/$defs/piece"
          },
          {
            "$ref": "#/$defs/card"
          }
        ]
      },
      "path": {
        "type": "string",
        "minLength": 1
      },
      "next": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string"
          },
          "title": {
            "type": "string"
          },
          "cost": {
            "type": "string"
          }
        },
        "required": ["id", "title"],
        "additionalProperties": false
      },
      "history": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "version": {
              "type": "integer",
              "minimum": 1
            },
            "status": {
              "enum": ["draft", "approved", "stale", "locked"]
            }
          },
          "required": ["version", "status"],
          "additionalProperties": false
        }
      }
    },
    "required": ["piece", "path"],
    "additionalProperties": false,
    "$defs": {
      "piece": {
        "type": "object",
        "properties": {
          "schema": {
            "const": "voyager.film-piece/1"
          },
          "stage": {
            "const": "treatment"
          },
          "id": {
            "enum": ["logline", "characters", "world", "beats", "scenes", "look"]
          },
          "title": {
            "type": "string",
            "minLength": 1
          },
          "status": {
            "enum": ["draft", "approved", "stale"]
          },
          "version": {
            "type": "integer",
            "minimum": 1
          },
          "approved": {
            "type": "string",
            "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
          },
          "basedOn": {
            "type": "object",
            "propertyNames": {
              "enum": ["logline", "characters", "world", "beats", "scenes", "look"]
            },
            "additionalProperties": {
              "type": "integer",
              "minimum": 1
            }
          },
          "summary": {
            "type": "string"
          },
          "items": {
            "$ref": "#/$defs/items"
          },
          "alternatives": {
            "type": "array",
            "minItems": 1,
            "maxItems": 3,
            "items": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string",
                  "minLength": 1
                },
                "label": {
                  "type": "string",
                  "minLength": 1
                },
                "why": {
                  "type": "string"
                },
                "items": {
                  "$ref": "#/$defs/items"
                }
              },
              "required": ["id", "label", "items"],
              "additionalProperties": false
            }
          },
          "chosenAlternative": {
            "type": "string"
          },
          "autoApproved": {
            "type": "boolean"
          },
          "types": {
            "type": "array",
            "minItems": 1,
            "uniqueItems": true,
            "items": {
              "enum": ["narrative", "commercial", "viral", "product"]
            }
          },
          "typeInputs": {
            "type": "object",
            "minProperties": 1,
            "properties": {
              "commercial": {
                "type": "object"
              },
              "viral": {
                "type": "object"
              },
              "product": {
                "type": "object"
              }
            },
            "additionalProperties": false
          }
        },
        "required": ["schema", "stage", "id", "title", "status", "version", "basedOn", "items"],
        "additionalProperties": false,
        "if": {
          "properties": {
            "id": {
              "not": {
                "const": "logline"
              }
            }
          }
        },
        "then": {
          "not": {
            "anyOf": [
              {
                "required": ["types"]
              },
              {
                "required": ["typeInputs"]
              }
            ]
          }
        }
      },
      "items": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[a-z0-9-]+$"
            },
            "kind": {
              "enum": [
                "logline",
                "benchmark",
                "character",
                "world",
                "tone",
                "beat",
                "scene",
                "line",
                "styleKey",
                "scopedLook",
                "ref"
              ]
            },
            "fields": {
              "type": "object",
              "additionalProperties": {
                "type": "string"
              }
            },
            "media": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "userEdited": {
              "type": "array",
              "items": {
                "type": "string"
              }
            }
          },
          "required": ["id", "kind", "fields"],
          "additionalProperties": false
        }
      },
      "card": {
        "type": "object",
        "properties": {
          "schema": {
            "const": "voyager.film-piece/2"
          },
          "stage": {
            "enum": ["treatment", "breakdown", "shot-list", "look-dev", "previs", "keyframes"]
          },
          "id": {
            "type": "string",
            "pattern": "^[a-z0-9-]+$"
          },
          "title": {
            "type": "string",
            "minLength": 1
          },
          "status": {
            "enum": ["draft", "approved", "stale", "locked"]
          },
          "version": {
            "type": "integer",
            "minimum": 1
          },
          "approved": {
            "type": "string",
            "pattern": "^\\d{4}-\\d{2}-\\d{2}$"
          },
          "basedOn": {
            "type": "object",
            "additionalProperties": {
              "type": "integer",
              "minimum": 1
            }
          },
          "summary": {
            "type": "string"
          },
          "items": {
            "$ref": "#/$defs/cardItems"
          },
          "alternatives": {
            "type": "array",
            "minItems": 1,
            "maxItems": 3,
            "items": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string",
                  "minLength": 1
                },
                "label": {
                  "type": "string",
                  "minLength": 1
                },
                "why": {
                  "type": "string"
                },
                "items": {
                  "$ref": "#/$defs/cardItems"
                }
              },
              "required": ["id", "label", "items"],
              "additionalProperties": false
            }
          },
          "chosenAlternative": {
            "type": "string"
          }
        },
        "required": ["schema", "stage", "id", "title", "status", "version", "items"],
        "additionalProperties": false
      },
      "cardItems": {
        "type": "array",
        "minItems": 1,
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "pattern": "^[A-Za-z0-9][A-Za-z0-9_.-]*$"
            },
            "kind": {
              "enum": [
                "logline",
                "benchmark",
                "character",
                "world",
                "tone",
                "beat",
                "scene",
                "line",
                "styleKey",
                "scopedLook",
                "ref",
                "piece",
                "prop",
                "set",
                "shot",
                "storyboard",
                "animatic",
                "keyframe"
              ]
            },
            "title": {
              "type": "string"
            },
            "group": {
              "type": "string"
            },
            "fields": {
              "type": "object",
              "additionalProperties": {
                "type": "string"
              }
            },
            "readOnly": {
              "$ref": "#/$defs/names"
            },
            "advanced": {
              "$ref": "#/$defs/names"
            },
            "decisions": {
              "type": "array",
              "items": {
                "enum": ["keep", "edit", "redo", "drop", "reopen"]
              }
            },
            "media": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1
              }
            },
            "mediaRoles": {
              "type": "array",
              "items": {
                "enum": ["start", "end", "clip", "image", "animatic"]
              }
            },
            "cost": {
              "type": "string"
            },
            "userEdited": {
              "$ref": "#/$defs/names"
            }
          },
          "required": ["id", "kind", "fields"],
          "additionalProperties": false
        }
      },
      "names": {
        "type": "array",
        "items": {
          "type": "string"
        }
      }
    }
  },
  "actions": [
    {
      "id": "review_piece",
      "label": "Send card review",
      "inputSchema": {
        "type": "object",
        "properties": {
          "pieceId": {
            "type": "string",
            "pattern": "^[a-z0-9-]+$"
          },
          "stage": {
            "enum": ["treatment", "breakdown", "shot-list", "look-dev", "previs", "keyframes"]
          },
          "version": {
            "type": "integer",
            "minimum": 1
          },
          "decision": {
            "enum": ["revise", "approve", "reopen"]
          },
          "alternativeId": {
            "type": "string",
            "minLength": 1
          },
          "note": {
            "type": "string",
            "minLength": 1
          },
          "items": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "itemId": {
                  "type": "string",
                  "pattern": "^[A-Za-z0-9][A-Za-z0-9_.-]*$"
                },
                "decision": {
                  "enum": ["keep", "edit", "redo", "drop", "reopen"]
                },
                "edits": {
                  "type": "object",
                  "minProperties": 1,
                  "additionalProperties": {
                    "type": "string"
                  }
                },
                "note": {
                  "type": "string",
                  "minLength": 1
                },
                "mediaId": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "required": ["itemId", "decision"],
              "additionalProperties": false
            }
          },
          "added": {
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "properties": {
                "kind": {
                  "enum": ["character", "beat", "scene", "benchmark", "styleKey"]
                },
                "fields": {
                  "type": "object",
                  "minProperties": 1,
                  "additionalProperties": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "required": ["kind", "fields"],
              "additionalProperties": false,
              "allOf": [
                {
                  "if": { "properties": { "kind": { "const": "character" } } },
                  "then": {
                    "properties": {
                      "fields": {
                        "propertyNames": { "enum": ["name", "role", "want", "flaw", "arc", "look"] }
                      }
                    }
                  }
                },
                {
                  "if": { "properties": { "kind": { "const": "beat" } } },
                  "then": {
                    "properties": {
                      "fields": {
                        "propertyNames": { "enum": ["label", "beat", "act", "runtimeSec"] }
                      }
                    }
                  }
                },
                {
                  "if": { "properties": { "kind": { "const": "scene" } } },
                  "then": {
                    "properties": {
                      "fields": {
                        "propertyNames": {
                          "enum": ["code", "place", "time", "change", "runtimeSec", "script"]
                        }
                      }
                    }
                  }
                },
                {
                  "if": { "properties": { "kind": { "const": "benchmark" } } },
                  "then": {
                    "properties": {
                      "fields": { "propertyNames": { "enum": ["work", "take", "avoid"] } }
                    }
                  }
                },
                {
                  "if": { "properties": { "kind": { "const": "styleKey" } } },
                  "then": {
                    "properties": {
                      "fields": {
                        "propertyNames": {
                          "enum": ["styleKey", "palette", "camera", "aspect", "moodFrom"]
                        }
                      }
                    }
                  }
                }
              ]
            }
          }
        },
        "required": ["pieceId", "version", "decision", "items"],
        "additionalProperties": false,
        "allOf": [
          {
            "if": { "properties": { "decision": { "const": "reopen" } } },
            "then": { "not": { "required": ["added"] } }
          },
          {
            "if": { "required": ["stage"] },
            "then": { "not": { "required": ["added"] } }
          },
          {
            "if": { "properties": { "pieceId": { "const": "world" } } },
            "then": { "not": { "required": ["added"] } }
          },
          {
            "if": { "properties": { "pieceId": { "const": "logline" } } },
            "then": {
              "properties": {
                "added": { "items": { "properties": { "kind": { "const": "benchmark" } } } }
              }
            }
          },
          {
            "if": { "properties": { "pieceId": { "const": "characters" } } },
            "then": {
              "properties": {
                "added": { "items": { "properties": { "kind": { "const": "character" } } } }
              }
            }
          },
          {
            "if": { "properties": { "pieceId": { "const": "beats" } } },
            "then": {
              "properties": {
                "added": { "items": { "properties": { "kind": { "const": "beat" } } } }
              }
            }
          },
          {
            "if": { "properties": { "pieceId": { "const": "scenes" } } },
            "then": {
              "properties": {
                "added": { "items": { "properties": { "kind": { "const": "scene" } } } }
              }
            }
          },
          {
            "if": { "properties": { "pieceId": { "const": "look" } } },
            "then": {
              "properties": {
                "added": {
                  "maxItems": 1,
                  "items": { "properties": { "kind": { "const": "styleKey" } } }
                }
              }
            }
          }
        ]
      },
      "delivery": {
        "kind": "agent"
      },
      "cardinality": "repeatable"
    }
  ],
  "bindings": [],
  "exampleInputs": {
    "piece": {
      "schema": "voyager.film-piece/1",
      "stage": "treatment",
      "id": "logline",
      "title": "Logline",
      "status": "draft",
      "version": 1,
      "basedOn": {},
      "items": [
        {
          "id": "logline",
          "kind": "logline",
          "fields": {
            "logline": "At dawn, a lighthouse keeper's forgotten brass telescope splits the first sunbeam into a small rainbow, and a sleeping cat wakes to chase it."
          }
        },
        {
          "id": "kitbull",
          "kind": "benchmark",
          "fields": {
            "work": "Pixar short 'Kitbull' (the cat beats)",
            "take": "wordless feline curiosity told in a glance and a paw",
            "avoid": "big emotional stakes; this is a breath, not a drama"
          }
        },
        {
          "id": "tree-of-life",
          "kind": "benchmark",
          "fields": {
            "work": "Terrence Malick dawn interiors (The Tree of Life)",
            "take": "light as the moving character, soft warm interiors",
            "avoid": "handheld drift; our camera is still"
          }
        }
      ]
    },
    "path": "film/pieces/logline.json",
    "next": {
      "id": "characters",
      "title": "Characters"
    }
  },
  "fallback": "Review this card in the conversation: say keep, edit (with the new wording), redo (with what should change), drop or reopen for each item, describe any item to add, then say whether to approve the card."
}

/* The host supplies --voyager-* tokens and a baseline; its frame is the card. */
:root {
  --ink: var(--voyager-fg);
  --quiet: var(--voyager-muted-fg);
  --line: var(--voyager-border);
  --well: var(--voyager-muted);
  --hover: color-mix(in srgb, var(--ink) 5%, transparent);
  --pressed: color-mix(in srgb, var(--ink) 10%, transparent);
  /* Gold is the warning colour only: the out-of-date chip. */
  --warn: light-dark(#866234, #e0a458);
}
body {
  padding: 12px 14px;
  text-wrap: pretty;
}
/* The whole font, so buttons do not take the baseline's heavier weight. */
button,
textarea {
  font: inherit;
  color: inherit;
}
button {
  min-height: 0;
}
button:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--voyager-focus);
  outline-offset: 2px;
}
header,
footer,
.collapsed {
  display: flex;
  align-items: baseline;
  gap: 4px 8px;
}
header {
  flex-wrap: wrap;
  padding-bottom: 6px;
}
footer {
  flex-wrap: wrap;
  align-items: center;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}
.meta,
.types,
.alt-why,
.runtime,
[data-chip],
dt,
.acts button,
.edit-grid label,
.readonly,
.cost,
.role,
summary,
.tally,
.hint,
#status {
  font-size: 0.75rem;
  color: var(--quiet);
}
.number,
.path {
  font: 0.75rem var(--voyager-mono);
  color: var(--quiet);
}
h1 {
  margin: 0;
  font-size: 0.875rem;
  letter-spacing: 0;
}
h1,
b {
  font-weight: 600;
  white-space: nowrap;
}
header > :not(.meta, .path),
.collapsed > :not(.one) {
  flex-shrink: 0;
}
header > .path,
.one {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
header > .path {
  text-align: end;
}
.chip {
  padding: 0 6px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--warn) 16%, transparent);
  color: var(--warn);
  font-size: 0.6875rem;
  font-weight: 500;
}
[role="tablist"] {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  border-bottom: 1px solid var(--line);
}
[role="tab"] {
  margin-bottom: -1px;
  padding: 6px 8px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: none;
  text-align: start;
  color: var(--quiet);
  transition: color var(--voyager-motion);
}
[role="tab"]:hover,
[role="tab"][aria-selected="true"],
.acts button:hover,
.add:hover {
  color: var(--ink);
}
[role="tab"][aria-selected="true"] {
  border-bottom-color: var(--ink);
}
.alt-label {
  display: flex;
  gap: 6px;
  align-items: baseline;
  font-weight: 600;
  font-size: 0.8125rem;
}
/* A tab's why stays in its accessible name; the selected one is shown below. */
[role="tab"] .alt-why {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
p.alt-why {
  margin: 6px 0 0;
}
.item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 2px 12px;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}
.items > .item:first-child,
.group + .item {
  border-top: 0;
}
/* A group header (a scene, the characters) over its consecutive items. */
.group {
  margin: 0;
  padding: 10px 0 2px;
  border-top: 1px solid var(--line);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0;
  color: var(--quiet);
}
.items > .group:first-child {
  border-top: 0;
}
.cost {
  align-self: center;
  padding-inline-end: 4px;
  font-variant-numeric: tabular-nums;
  /* A first-last keyframe redo reads "$0.16 · redoes 2 stills"; it stays one line beside Redo. */
  white-space: nowrap;
}
.item-title {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 2px 8px;
  min-width: 0;
}
[data-chip] {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}
svg {
  width: 10px;
  height: 10px;
}
.item-body {
  grid-column: 1 / -1;
  min-width: 0;
}
[data-decision="drop"] .item-title b,
[data-decision="replaced"] .item-title b {
  text-decoration: line-through;
}
[data-decision="drop"] :is(.item-title, .item-body),
/* A replaced item's chip says why, so it stays readable. */
[data-decision="replaced"] :is(.item-title > :not([data-chip]), .item-body) {
  opacity: 0.5;
}
.acts {
  display: flex;
  gap: 2px;
  align-self: start;
}
.acts button,
.add {
  min-height: 24px;
  padding: 0 8px;
  border: 0;
  border-radius: 4px;
  background: none;
  transition:
    background var(--voyager-motion),
    color var(--voyager-motion);
}
.acts button:hover,
.add:hover:not(:disabled),
.btn:hover:not(:disabled) {
  background: var(--hover);
}
/* The user's own item goes after the last one; quiet, like a decision button. */
.add {
  display: grid;
  place-items: center;
  width: 24px;
  margin-top: 4px;
  padding: 0;
  color: var(--quiet);
}
.add svg {
  width: 12px;
  height: 12px;
}
.add:disabled {
  opacity: 0.45;
}
.acts button[aria-pressed="true"] {
  color: var(--ink);
  font-weight: 600;
  background: var(--pressed);
}
/* Items start as Keep; only a decision the user made is filled. */
.item:not([data-explicit]) .acts button[aria-pressed="true"]:not(:hover) {
  background: none;
}
p.value,
dd {
  white-space: pre-wrap;
}
p.value {
  margin: 2px 0 0;
  max-width: 72ch;
}
dl,
.edit-grid label {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  gap: 2px 10px;
}
dl {
  margin: 2px 0 0;
  font-size: 0.8125rem;
}
dt {
  padding-top: 1px;
}
dd {
  margin: 0;
  min-width: 0;
}
.edited {
  box-decoration-break: clone;
  background: linear-gradient(transparent 62%, color-mix(in srgb, var(--ink) 12%, transparent) 0);
}
dd.script {
  font: 0.75rem/1.55 var(--voyager-mono);
  padding-inline-start: 8px;
  border-inline-start: 2px solid var(--line);
}
.media,
.edit-grid {
  display: grid;
  gap: 6px;
  margin-top: 6px;
}
.media {
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 140px), 1fr));
}
.role {
  display: block;
  margin-top: 2px;
}
.media img,
.media video {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  border-radius: var(--voyager-radius);
  background: var(--well);
}
.readonly {
  display: grid;
  grid-template-columns: 84px minmax(0, 1fr);
  gap: 10px;
}
.readonly span {
  font-size: 0.8125rem;
  color: var(--ink);
  white-space: pre-wrap;
}
.advanced {
  margin-top: 4px;
}
summary {
  width: fit-content;
  cursor: pointer;
}
.target {
  margin-top: 6px;
}
.edit-grid label {
  gap: 10px;
  align-items: start;
  /* Match the display view's normal-weight captions, not the baseline label weight. */
  font-weight: 400;
}
textarea {
  display: block;
  width: 100%;
  field-sizing: content;
  min-height: calc(1lh + 14px);
  max-height: calc(12lh + 14px);
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: var(--voyager-radius);
  background: var(--voyager-bg);
  font-size: 0.8125rem;
  /* The baseline gives labels a heavier weight, which `font: inherit` would carry into the text. */
  font-weight: 400;
  line-height: 1.45;
  color: var(--ink);
}
textarea.mono {
  font-family: var(--voyager-mono);
  font-size: 0.75rem;
}
.note {
  margin-top: 6px;
}
.edit-foot {
  display: flex;
  justify-content: flex-end;
