const root = document.querySelector("#root");
const status = document.querySelector("#status");
const FALLBACK =
  "This film card could not be shown here. Review it in the conversation: say keep, edit (with the new wording), redo (with what should change) or drop for each item, describe any item to add, then say whether to approve it.";
const {
  PIECES,
  STAGES,
  DECISIONS,
  ROLE_LABEL,
  STATUS_LABEL,
  LABEL,
  TITLE_FIELDS,
  ADD_KIND,
  ADD_FIELDS,
  PLUS,
  PEN,
  inputError,
  invalidInputs,
} = globalThis.filmPieceKinds ?? {};
const { approvedPiece, folds, sendKeeping } = globalThis.filmPieceApproval ?? {};

let inputs, piece, card, alternatives, defaultAlternative, draftKey, draft, review;
let saves = Promise.resolve();
let busy = false;
const editing = new Set();
const resolved = new Map();
// Presented ids resolved again after a load error, until one loads: a broken file is asked for once.
const retried = new Set();

try {
  if (!invalidInputs || !approvedPiece || !folds || !sendKeeping)
    throw new Error("Missing film card resources. Reload Voyager and try again.");
  inputs = (await host.context.get()).inputs ?? {};
  const problem = invalidInputs(inputs);
  if (problem) throw inputError(problem);
  await mount();
} catch (error) {
  root.replaceChildren(el("p", { class: "fallback" }, FALLBACK));
  status.textContent = message(error);
  // An error screen cannot approve a film.
  host.diagnostics?.report(error);
}

async function mount() {
  piece = inputs.piece;
  // A stage card (/2) rather than a story piece (/1).
  card = piece.schema === "voyager.film-piece/2";
  // Decisions belong to one version; an older one is cleared.
  draftKey = `${piece.id}@${piece.version}`;
  draft = await host.drafts.read();
  // Keep accepted approvals visible (ENG-7202).
  const ok =
    !card &&
    piece.status === "draft" &&
    (await host.state.read().catch(() => null))?.value?.approved;
  if (ok?.from === piece.version && Array.isArray(ok.piece?.items))
    piece = { ...piece, summary: undefined, ...ok.piece };
  // A locked card shows what was locked, never this version's unsent decisions.
  const stored = piece.status === "locked" ? undefined : draft.value?.[draftKey];
  const outdated = Object.keys(draft.value ?? {}).filter(
    (key) => key !== draftKey && /^[a-z0-9-]+@\d+$/.test(key),
  );
  if (outdated.length)
    void save(Object.fromEntries(outdated.map((key) => [key, null]))).catch(() => {});
  alternatives = piece.alternatives ?? [];
  defaultAlternative = piece.chosenAlternative ?? alternatives[0]?.id;
  // An array: a merge patch replaces it whole, so a removed edit stays removed.
  review = {
    alternativeId: alternative(stored?.alternativeId)?.id ?? defaultAlternative ?? null,
    items: Array.isArray(stored?.items) ? stored.items : [],
    note: typeof stored?.note === "string" ? stored.note : "",
    // The user's own items, `+`-prefixed so no piece item id can match; a blank one is never kept.
    added: Array.isArray(stored?.added) ? stored.added.filter(addable) : [],
  };
  render();
}

function addable(entry) {
  const fields = Object.entries(entry?.fields ?? {});
  return (
    !card &&
    entry?.kind === ADD_KIND[piece.id] &&
    /^\+/.test(entry.id) &&
    fields.length > 0 &&
    fields.every(
      ([field, value]) =>
        ADD_FIELDS[entry.kind].includes(field) && typeof value === "string" && /\S/.test(value),
    )
  );
}

function save(patch) {
  const pending = saves.then(async () => {
    draft = await host.drafts.patch({ expectedDraftRevision: draft.revision, patch });
  });
  // A failed write re-reads the draft so the next one has a fresh revision.
  saves = pending.catch(async (error) => {
    status.textContent = message(error);
    draft = await host.drafts.read().catch(() => draft);
  });
  return pending;
}

function persist() {
  return save({ [draftKey]: review }).catch(() => {});
}

function alternative(id) {
  return alternatives.find((entry) => entry.id === id);
}

// piece.items belongs to the chosen alternative; with none chosen, each tab shows its own.
function shownItems() {
  if (
    !alternatives.length ||
    piece.status === "locked" ||
    review.alternativeId === piece.chosenAlternative
  )
    return piece.items;
  return alternative(review.alternativeId).items;
}

function stateOf(itemId) {
  const fresh = { itemId, decision: "keep", edits: {}, note: "" };
  return review.items.find((entry) => entry.itemId === itemId) ?? fresh;
}

function update(itemId, changes) {
  const others = review.items.filter((entry) => entry.itemId !== itemId);
  review = { ...review, items: [...others, { ...stateOf(itemId), ...changes, itemId }] };
}

// The look holds one style key, so a saved one of the user's replaces the piece's: shown
// replaced and sent as a drop, its own decision kept for when the user's is removed.
function decisionOf(item) {
  const replaced =
    piece.id === "look" &&
    item.kind === "styleKey" &&
    !item.id.startsWith("+") &&
    savedAdded().length > 0;
  return replaced ? "replaced" : stateOf(item.id).decision;
}

function counts() {
  const tally = { edit: 0, redo: 0, drop: 0, reopen: 0 };
  for (const item of shownItems()) {
    const decision = decisionOf(item);
    if (decision in tally) tally[decision] += 1;
  }
  return { ...tally, added: savedAdded().length };
}

// A Redo, a Reopen or a card note asks for text the user has not seen: the card goes back.
function sendsBack() {
  const tally = counts();
  return tally.redo + tally.reopen + (card && review.note.trim() ? 1 : 0);
}

// The decisions an item offers; Edit only when it has a field the user may change.
function choices(item) {
  const allowed = item.decisions ?? ["keep", "edit", "redo", "drop"];
  const editable = Object.keys(item.fields).some((field) => !item.readOnly?.includes(field));
  return DECISIONS.filter((choice) => allowed.includes(choice) && (choice !== "edit" || editable));
}

function payload(decision) {
  const note = review.note.trim();
  return {
    pieceId: piece.id,
    ...(card ? { stage: piece.stage } : {}),
    version: piece.version,
    decision,
    ...(alternatives.length ? { alternativeId: review.alternativeId } : {}),
    ...(card && note ? { note } : {}),
    items: shownItems().map((item) => {
      const state = stateOf(item.id);
      const decision = decisionOf(item) === "replaced" ? "drop" : state.decision;
      const edits = decision === "drop" ? {} : (state.edits ?? {});
      const note = (state.note ?? "").trim();
      const back = decision === "redo" || decision === "reopen";
      const targeted = decision === "redo" && item.media?.includes(state.mediaId);
      return {
        itemId: item.id,
        decision,
        ...(Object.keys(edits).length ? { edits } : {}),
        ...(back && note ? { note } : {}),
        ...(targeted ? { mediaId: state.mediaId } : {}),
      };
    }),
    ...(savedAdded().length
      ? { added: savedAdded().map((entry) => ({ kind: entry.kind, fields: entry.fields })) }
      : {}),
  };
}

// A new row is blank until saved, and a blank row is never counted or sent.
function savedAdded() {
  return review.added.filter((entry) => Object.keys(entry.fields).length);
}

// Open editors are committed before sending, so typed text is never lost.
function sendReview(decision) {
  for (const itemId of [...editing]) commitEdit(itemId);
  persist();
  // With nothing sent back, revisions approve too, so both fold the widget and read as an approval.
  void submit(payload(decision), !sendsBack());
}

async function submit(body, collapse) {
  const approval =
    collapse && !card
      ? approvedPiece(
          piece,
          body.decision,
          review.alternativeId,
          savedAdded(),
          (item) => ({
            drop: ["drop", "replaced"].includes(decisionOf(item)),
            edits: stateOf(item.id).edits ?? {},
          }),
          shownItems(),
        )
      : undefined;
  busy = true;
  render();
  try {
    await saves;
    const serialized = JSON.stringify(body);
    const existing = draft.value?._request_review_piece;
    const request =
      existing?.payload === serialized
        ? existing
        : { payload: serialized, key: crypto.randomUUID() };
    await save({ _request_review_piece: request });
    const receipt = await sendKeeping(host, approval, body.version, () =>
      host.conversation.submit("review_piece", body, { requestKey: request.key, collapse }),
    );
    if (approval && folds(receipt)) piece = { ...piece, ...approval };
    await save({ _request_review_piece: null });
    status.textContent =
      body.decision === "reopen"
        ? `Reopen sent (${receipt.status}).`
        : collapse
          ? `Approval sent (${receipt.status}).`
          : `Revisions sent (${receipt.status}). The next version replaces this one.`;
  } catch (error) {
    status.textContent = message(error);
  } finally {
    busy = false;
    render();
  }
}

function commitEdit(itemId) {
  editing.delete(itemId);
  if (itemId.startsWith("+")) {
    const fields = {};
    for (const area of root.querySelectorAll(`textarea[data-edit="${itemId}"]`))
      if (area.value.trim()) fields[area.dataset.field] = area.value.trim();
    review = {
      ...review,
      added: review.added.flatMap((entry) =>
        entry.id !== itemId ? [entry] : Object.keys(fields).length ? [{ ...entry, fields }] : [],
      ),
    };
    return;
  }
  const item = shownItems().find((candidate) => candidate.id === itemId);
  const edits = {};
  for (const area of root.querySelectorAll(`textarea[data-edit="${itemId}"]`)) {
    const value = area.value.trim();
    const field = area.dataset.field;
    if (value !== item.fields[field] && !item.readOnly?.includes(field)) edits[field] = value;
  }
  const decision = stateOf(itemId).decision;
  const back = decision === "redo" || decision === "reopen";
  update(itemId, {
    decision: back ? decision : Object.keys(edits).length ? "edit" : "keep",
    edits,
  });
}

function decide(item, choice) {
  const state = stateOf(item.id);
  if (choice === "edit") editing.add(item.id);
  else editing.delete(item.id);
  if (choice === "remove")
    review = { ...review, added: review.added.filter((entry) => entry.id !== item.id) };
  // Keep means as written: it drops this version's edits and redo note.
  if (choice === "keep") update(item.id, { decision: "keep", edits: {}, note: "" });
  if (choice === "redo" || choice === "reopen") update(item.id, { decision: choice });
  if (choice === "drop") {
    const undo = Object.keys(state.edits ?? {}).length ? "edit" : "keep";
    update(item.id, { decision: state.decision === "drop" ? undo : "drop" });
  }
  persist();
  render(
    choice === "edit"
      ? `textarea[data-edit="${item.id}"]`
      : choice === "redo" || choice === "reopen"
        ? `textarea[data-note="${item.id}"]`
        : choice === "remove"
          ? "#add"
          : choiceButton(item.id, choice),
  );
}

function choiceButton(itemId, choice) {
  return `[data-item="${itemId}"] button[data-choice="${choice}"]`;
}

// A locked card is shown whole, its items read-only; approved and out-of-date ones fold to a line.
function render(focusSelector) {
  const open = piece.status === "draft" || piece.status === "locked";
  root.replaceChildren(open ? renderDraft() : renderCollapsed());
  if (focusSelector) root.querySelector(focusSelector)?.focus({ preventScroll: true });
}

// Quiet version and status; out of date, the one warning, is a chip.
function heading(title, ...meta) {
  const stale = piece.status === "stale";
  const words = [`v${piece.version}`, ...(stale ? [] : [STATUS_LABEL[piece.status]]), ...meta];
  return [
    el("span", { class: "number" }, card ? STAGES[piece.stage] : PIECES[piece.id]),
    title,
    el("span", { class: "meta" }, words.join(" · ")),
    ...(stale ? [el("span", { class: "chip" }, STATUS_LABEL.stale)] : []),
  ];
}

// Applied by editing the piece back to draft: the same version while nothing is built on it yet,
// otherwise a new one that stales what is built on it.
function reopenButton() {
  const reopen = button("Reopen", {
    class: "btn",
    id: "reopen",
    title: `Back to draft. Any ${card ? "stage" : "piece"} already built on it goes out of date.`,
  });
  reopen.disabled = busy;
  reopen.onclick = () =>
    submit({
      pieceId: piece.id,
      ...(card ? { stage: piece.stage } : {}),
      version: piece.version,
      decision: "reopen",
      items: [],
    });
  return reopen;
}

function renderCollapsed() {
  const summary = piece.summary || summaryLine();
  return el(
    "div",
    { class: "collapsed" },
    ...heading(el("b", {}, piece.title)),
    el("span", { class: "one", title: summary }, summary),
    reopenButton(),
  );
}

function summaryLine() {
  const items = piece.items;
  if (card || piece.id !== "beats") return items.map(itemTitle).join(" · ");
  const total = items.reduce(
    (sum, item) => sum + (Number.parseFloat(item.fields.runtimeSec) || 0),
    0,
  );
  return `${items.length} beats · ${formatSeconds(total)}`;
}

function renderDraft() {
  // Shown from the film folder on; the full path stays in the tooltip.
  const path = `/${inputs.path.replace(/\\/g, "/")}`;
  const film = path.lastIndexOf("/film/");
  const earlier = (inputs.history ?? []).map(
    (entry) => `v${entry.version} ${STATUS_LABEL[entry.status].toLowerCase()}`,
  );
  const section = el(
    "section",
    { "aria-labelledby": "piece-title" },
    el(
      "header",
      {},
      ...heading(
        el("h1", { id: "piece-title" }, piece.title),
        ...(earlier.length ? [`Earlier: ${earlier.join(", ")}`] : []),
      ),
      el(
        "span",
        { class: "path", title: inputs.path },
        film < 0 ? path.split("/").pop() : path.slice(film + 1),
      ),
    ),
  );
  // The film's types, approved with the logline: shown, not edited.
  if (piece.types)
    section.append(
      el(
        "div",
        { class: "types" },
        `Types: ${piece.types.map(label).join(" · ")}`,
        el("dl", {}, ...rows(piece.typeInputs ?? {}, "")),
      ),
    );
  const items = el("div", { class: "items", id: "items" });
  // A locked card shows its chosen direction only.
  if (alternatives.length && piece.status !== "locked") {
    section.append(...renderAlternatives());
    items.setAttribute("role", "tabpanel");
    const selected = alternatives.indexOf(alternative(review.alternativeId));
    items.setAttribute("aria-labelledby", `alternative-${selected}`);
  }
  // Consecutive items of one group share its header.
  items.append(
    ...shownItems().flatMap((item, index, list) => [
      ...(item.group && item.group !== list[index - 1]?.group
        ? [el("h2", { class: "group" }, item.group)]
        : []),
      renderItem(item),
    ]),
    ...review.added.map(renderItem),
  );
  // Only a story piece takes the user's own items, and never once locked.
  const kind = !card && piece.status !== "locked" && ADD_KIND[piece.id];
  // The look holds exactly one style key, so the user's own replaces it and there is one at most.
  if (kind && !(kind === "styleKey" && review.added.length)) {
    const name = `Add ${kindName(kind)}`;
    const add = button("", { class: "add", id: "add", "aria-label": name, title: name });
    add.insertAdjacentHTML("afterbegin", PLUS);
    add.disabled = busy;
    add.onclick = () => {
      const id = `+${crypto.randomUUID()}`;
      review = { ...review, added: [...review.added, { id, kind, fields: {} }] };
      editing.add(id);
      render(`textarea[data-edit="${id}"]`);
    };
    items.append(add);
  }
  section.append(items);
  // A locked card's only control is Reopen.
  section.append(
    piece.status === "locked"
      ? el("footer", {}, el("div", { class: "actions" }, reopenButton()))
      : renderFooter(),
  );
  return section;
}

function renderAlternatives() {
  const pick = (target) => {
    if (target.id !== review.alternativeId) {
      // Another direction has other items, so decisions do not carry over.
      review = { alternativeId: target.id, items: [], note: review.note, added: [] };
      editing.clear();
      persist();
    }
    render(`#alternative-${alternatives.indexOf(target)}`);
  };
  const tabs = alternatives.map((entry, index) => {
    const selected = entry.id === review.alternativeId;
    const tab = button(
      el(
        "span",
        { class: "alt-label" },
        el("span", { class: "number" }, "ABC"[index]),
        entry.label,
      ),
      {
        role: "tab",
        // By position: an alternative id is free text, not a DOM id.
        id: `alternative-${index}`,
        "aria-selected": String(selected),
        "aria-controls": "items",
        tabindex: selected ? "0" : "-1",
        "data-alternative": entry.id,
      },
    );
    if (entry.why) tab.append(el("span", { class: "alt-why" }, entry.why));
    tab.onclick = () => pick(entry);
    tab.onkeydown = (event) => {
      const step = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key];
      const count = alternatives.length;
      const target =
        event.key === "Home"
          ? alternatives[0]
          : event.key === "End"
            ? alternatives.at(-1)
            : step && alternatives[(index + step + count) % count];
      if (!target) return;
      event.preventDefault();
      pick(target);
    };
    return tab;
  });
  const why = alternative(review.alternativeId).why;
  return [
    el("div", { role: "tablist", "aria-label": "Alternatives" }, ...tabs),
    ...(why ? [el("p", { class: "alt-why", "aria-hidden": "true" }, why)] : []),
  ];
}

function renderItem(item) {
  const added = item.id.startsWith("+");
  const state = stateOf(item.id);
  const decision = decisionOf(item);
  const edits = state.edits ?? {};
  const userEdited = [...new Set([...(item.userEdited ?? []), ...Object.keys(edits)])];
  const title = el("div", { class: "item-title" }, el("b", {}, itemTitle(item)));
  const runtime = item.fields.runtimeSec;
  if (runtime !== undefined && Number.isFinite(Number(runtime)))
    title.append(
      el("span", { class: "runtime" }, formatSeconds(Number(edits.runtimeSec ?? runtime))),
    );
  if (decision === "replaced")
    title.append(el("span", { "data-chip": "replaced" }, "Replaced by yours"));
  else if (added) {
    const chip = el("span", { "data-chip": "edited" }, "You added");
    chip.insertAdjacentHTML("afterbegin", PLUS);
    title.append(chip);
  } else if (userEdited.length) {
    const fields = userEdited.map((field) => label(field).toLowerCase()).join(", ");
    const edited = el("span", { "data-chip": "edited" }, `You edited · ${fields}`);
    edited.insertAdjacentHTML("afterbegin", PEN);
    title.append(edited);
  }

  const locked = piece.status === "locked";
  const shown = locked || decision === "replaced" ? [] : added ? ["edit", "remove"] : choices(item);
  const acts = shown.flatMap((choice) => {
    const pressed = editing.has(item.id) ? choice === "edit" : state.decision === choice;
    const text =
      choice === "drop" && state.decision === "drop"
        ? "Undo"
        : choice[0].toUpperCase() + choice.slice(1);
    const act = button(text, { "data-choice": choice, "aria-pressed": String(pressed) });
    act.disabled = busy;
    act.onclick = () => decide(item, choice);
    // A paid redo shows its price beside it.
    return choice === "redo" && item.cost ? [act, el("span", { class: "cost" }, item.cost)] : [act];
  });

  const body = el(
    "div",
    { class: "item-body" },
    editing.has(item.id)
      ? renderEditor(
          added
            ? { ...item, fields: Object.fromEntries(ADD_FIELDS[item.kind].map((f) => [f, ""])) }
            : item,
          added ? item.fields : edits,
        )
      : renderFields(item, edits, userEdited),
  );
  if (item.media?.length) body.append(renderMedia(item));
  if (decision === "redo" && item.media?.length > 1) body.append(renderTarget(item, state));
  if (decision === "redo" || decision === "reopen") {
    const note = el("textarea", {
      class: "note",
      rows: "2",
      "data-note": item.id,
      placeholder: "What should change?",
      "aria-label": `What should change in ${itemTitle(item)}`,
    });
    note.value = state.note ?? "";
    note.oninput = () => update(item.id, { note: note.value });
    note.onchange = persist;
    body.append(note);
  }
  return el(
    "article",
    {
      class: "item",
      "data-item": item.id,
      "data-decision": decision,
      ...(added || editing.has(item.id) || review.items.some((entry) => entry.itemId === item.id)
        ? { "data-explicit": "" }
        : {}),
    },
    title,
    ...(locked || decision === "replaced"
      ? []
      : [
          el(
            "div",
            { class: "acts", role: "group", "aria-label": `Decision for ${itemTitle(item)}` },
            ...acts,
          ),
        ]),
    body,
  );
}

// Which of an item's media a redo is for: all of them, or one (a keyframe's end frame, say).
function renderTarget(item, state) {
  const target = item.media.includes(state.mediaId) ? state.mediaId : undefined;
  const pick = (mediaId, text, index) => {
    const act = button(text, {
      "data-target": mediaId ?? "",
      "data-target-index": String(index),
      "aria-pressed": String(mediaId === target),
    });
    act.disabled = busy;
    act.onclick = () => {
      update(item.id, { mediaId });
      persist();
      // By position: a presented id is free text, not a selector.
      render(`[data-item="${item.id}"] button[data-target-index="${index}"]`);
    };
    return act;
  };
  return el(
    "div",
    { class: "acts target", role: "group", "aria-label": `What to redo in ${itemTitle(item)}` },
    pick(undefined, "All", -1),
    ...item.media.map((id, index) =>
      pick(id, roleLabel(item, index) || `Image ${index + 1}`, index),
    ),
  );
}

function roleLabel(item, index) {
  const role = item.mediaRoles?.[index];
  return role && Object.hasOwn(ROLE_LABEL, role) ? ROLE_LABEL[role] : "";
}

function renderFields(item, edits, userEdited) {
  const skip = !card && Object.hasOwn(TITLE_FIELDS, item.kind) ? TITLE_FIELDS[item.kind] : [];
  const shown = Object.keys(item.fields).filter((field) => !skip.includes(field));
  const fields = shown.filter((field) => !item.advanced?.includes(field));
  const advanced = shown.filter((field) => item.advanced?.includes(field));
  // A user-written value is marked inline, so the wash follows the text.
  const value = (field) => {
    const text = valueOf(item, edits, field);
    return userEdited.includes(field) ? el("span", { class: "edited" }, text) : text;
  };
  if (
    fields.length === 1 &&
    !advanced.length &&
    ["logline", "world", "tone", "line"].includes(item.kind)
  )
    return el("p", { class: "value" }, value(fields[0]));
  const rows = (names) =>
    names.flatMap((field) => [
      el("dt", {}, label(field)),
      el("dd", field === "script" ? { class: "script" } : {}, value(field)),
    ]);
  const list = el("dl", {}, ...rows(fields));
  return advanced.length ? el("div", {}, list, disclosure(el("dl", {}, ...rows(advanced)))) : list;
}

// Advanced fields (a shot's joins) fold under a disclosure, in the view and the editor alike.
function disclosure(content, open) {
  const summary = el("summary", {}, piece.stage === "shot-list" ? "Joins" : "More");
  return el("details", { class: "advanced", ...(open ? { open: "" } : {}) }, summary, content);
}

function renderEditor(item, edits) {
  const row = (field) => {
    // A read-only field is shown, not edited (a shot's dialogue belongs to the treatment).
    if (item.readOnly?.includes(field))
      return el(
        "div",
        { class: "readonly", "data-readonly": field },
        label(field),
        el("span", {}, item.fields[field]),
      );
    const area = el("textarea", {
      "data-edit": item.id,
      "data-field": field,
      rows: field === "runtimeSec" || field === "code" ? "1" : "2",
      ...(field === "script" ? { class: "mono" } : {}),
    });
    area.value = valueOf(item, edits, field);
    return el("label", {}, label(field), area);
  };
  const fields = Object.keys(item.fields);
  const rows = fields.filter((field) => !item.advanced?.includes(field)).map(row);
  const advanced = fields.filter((field) => item.advanced?.includes(field));
  const cancel = button("Cancel", { class: "btn", "data-edit-action": "cancel" });
  const done = button("Save edit", { class: "btn primary", "data-edit-action": "save" });
  // A new row never saved is dropped on Cancel; a row saved blank, on Save. Focus then falls to Add.
  const after = `${choiceButton(item.id, "edit")}, #add`;
  cancel.onclick = () => {
    editing.delete(item.id);
    const kept = (entry) => entry.id !== item.id || Object.keys(entry.fields).length;
    review = { ...review, added: review.added.filter(kept) };
    render(after);
  };
  done.onclick = () => {
    commitEdit(item.id);
    // A saved style key of the user's replaces the piece's, closing its editor with what was typed.
    for (const other of shownItems())
      if (editing.has(other.id) && decisionOf(other) === "replaced") commitEdit(other.id);
    persist();
    render(after);
  };
  const foot = el("div", { class: "edit-foot" }, cancel, done);
  const more = advanced.length
    ? [disclosure(el("div", { class: "edit-grid" }, ...advanced.map(row)), true)]
    : [];
  return el("div", { class: "edit-grid" }, ...rows, ...more, foot);
}

// Media are presented-file ids the host resolves; no project path reaches here.
function renderMedia(item) {
  const slots = item.media.map((id, index) => {
    const caption = roleLabel(item, index);
    const slot = el("div", caption ? { "data-role": item.mediaRoles[index] } : {});
    const load = () =>
      host.assets
        .resolve({ presentedId: id })
        .then((asset) => {
          resolved.set(id, asset);
          show(asset);
        })
        .catch((error) => {
          slot.textContent = message(error);
        });
    const show = (asset) => {
      const media = asset.mimeType?.startsWith("video/")
        ? el("video", { muted: "", controls: "", preload: "metadata" })
        : el("img", { alt: asset.fileName ?? `${itemTitle(item)} reference` });
      // A signed URL expires after a few minutes: on a media error, resolve it again once.
      media.onerror = () => {
        if (retried.has(id)) return;
        retried.add(id);
        void load();
      };
      media.onload = media.onloadedmetadata = () => retried.delete(id);
      media.src = asset.url;
      slot.replaceChildren(media, ...(caption ? [el("span", { class: "role" }, caption)] : []));
    };
    if (resolved.has(id)) show(resolved.get(id));
    else void load();
    return slot;
  });
  return el("div", { class: "media" }, ...slots);
}

function renderFooter() {
  const switched = alternatives.length > 0 && review.alternativeId !== defaultAlternative;
  const next = inputs.next;
  const send = button("", { class: "btn", id: "send" });
  send.onclick = () => sendReview("revise");
  // Approving a card that shows the next step's cost is the user's spend confirmation.
  const approve = button(
    next?.cost ? `Approve — starts ${next.title} (about ${next.cost})` : "Approve as is",
    { class: "btn primary", id: "approve" },
  );
  approve.onclick = () => {
    if (!sendsBack()) sendReview("approve");
  };
  const tally = el("span", { class: "tally", id: "tally" });
  // Kept in step while the card note is typed, so a click right after typing still lands.
  const sync = () => {
    const counted = counts();
    const back = sendsBack();
    const pending = counted.redo + counted.drop + counted.edit + counted.reopen + counted.added;
    // Only what sends the card back revises it; anything else approves it with the changes.
    const action = back ? "Send revisions" : "Approve with edits";
    send.textContent = pending ? `${action} (${pending})` : action;
    send.disabled = busy || (!pending && !switched && !back);
    // A Redo, a Reopen or a note asks for text the user has not seen, so it blocks approval.
    approve.disabled = busy || back > 0;
    approve.title = !back
      ? ""
      : counted.redo
        ? "Send the redo first"
        : counted.reopen
          ? "Send the reopen first"
          : "Send the note first";
    const words = [
      counted.edit && `${counted.edit} edited`,
      counted.redo && `${counted.redo} to redo`,
      counted.reopen && `${counted.reopen} to reopen`,
      counted.drop && `${counted.drop} to drop`,
      counted.added && `${counted.added} added`,
    ].filter(Boolean);
    tally.textContent = words.join(" · ") || "All kept";
  };
  sync();
  const hint = !next
    ? ""
    : next.cost
      ? `Approving, with or without edits, starts ${next.title} (about ${next.cost}). `
      : `Approving starts ${next.title}. `;
  const footer = el(
    "footer",
    {},
    tally,
    el("div", { class: "actions" }, send, approve),
    el("p", { class: "hint" }, `${hint}Edits are used word for word.`),
  );
  if (!card) return footer;
  // A note for the card as a whole: an item to add, a shot to split.
  const note = el("textarea", {
    class: "note",
    id: "card-note",
    rows: "2",
    placeholder: "Anything to add or change across the card?",
    "aria-label": `Note on ${piece.title}`,
  });
  note.value = review.note;
  note.disabled = busy;
  note.oninput = () => {
    review = { ...review, note: note.value };
    sync();
  };
  note.onchange = persist;
  footer.prepend(note);
  return footer;
}

function itemTitle(item) {
  if (item.title) return item.title;
  if (card) return item.id;
  const fields = item.fields;
  if (item.kind === "character" && fields.name) return fields.name;
  if (item.kind === "beat" && fields.label) return fields.label;
  // A scene the user added often has a place but no code yet.
  if (item.kind === "scene" && (fields.code || fields.place))
    return [fields.code, fields.place].filter(Boolean).join(" · ");
  if (item.kind === "benchmark" && fields.work) return fields.work;
  if (item.id.startsWith("+")) return `New ${kindName(item.kind)}`;
  // An unnamed character or scene shows its bare kind; other kinds, their label.
  return item.kind === "character" || item.kind === "scene" ? item.kind : label(item.kind);
}

// A dt/dd per value; list entries share their list's label.
function rows(value, name) {
  if (value === null || typeof value !== "object")
    return [el("dt", {}, name), el("dd", {}, String(value))];
  return Object.entries(value).flatMap(([key, entry]) =>
    rows(entry, Array.isArray(value) ? name : `${name && `${name} · `}${label(key)}`),
  );
}

// The kind, not its field label: a beat's `beat` field reads "What happens".
function kindName(kind) {
  return kind.replace(/[A-Z]/, (c) => ` ${c.toLowerCase()}`);
}

function label(field) {
  if (Object.hasOwn(LABEL, field)) return LABEL[field];
  return field.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^./, (c) => c.toUpperCase());
}

function valueOf(item, edits, field) {
  return Object.hasOwn(edits, field) ? edits[field] : item.fields[field];
}

function formatSeconds(seconds) {
  if (seconds < 60) return `${Number.isInteger(seconds) ? seconds : seconds.toFixed(1)} s`;
  const minutes = Math.floor(seconds / 60);
  const rest = Math.round(seconds % 60);
  return rest === 0 ? `${minutes} min` : `${minutes} min ${rest} s`;
}

function message(error) {
  return error?.message ?? String(error);
}

function el(tag, attributes, ...children) {
  const node = document.createElement(tag);
  for (const [name, value] of Object.entries(attributes ?? {})) node.setAttribute(name, value);
  node.append(...children);
  return node;
}

function button(content, attributes) {
  return el("button", { type: "button", ...attributes }, content);
}

// The film card's vocabulary and input check, shared with index.js through one global: the seeded
// page inlines both module scripts into one document, so neither can import the other.
const PIECES = {
  logline: "1.1",
  characters: "1.2",
  world: "1.3",
  beats: "1.4",
  scenes: "1.5",
  look: "1.6",
};
// A stage card's number in the staged production table.
const STAGES = {
  treatment: "1",
  breakdown: "2",
  "shot-list": "3",
  "look-dev": "4a",
  previs: "4b",
  keyframes: "5",
};
const KINDS =
  "logline benchmark character world tone beat scene line styleKey scopedLook ref".split(" ");
const CARD_KINDS = [...KINDS, ..."piece prop set shot storyboard animatic keyframe".split(" ")];
const DECISIONS = ["keep", "edit", "redo", "drop", "reopen"];
const ROLE_LABEL = { start: "Start", end: "End", clip: "Clip", image: "", animatic: "Animatic" };
const STATUS_LABEL = {
  draft: "Draft",
  approved: "Approved",
  stale: "Out of date",
  locked: "Locked",
};
// Only labels that differ from the title-cased field name.
const LABEL = {
  want: "Wants",
  label: "Beat",
  beat: "What happens",
  runtimeSec: "Seconds",
  code: "Scene",
  place: "Slugline",
  change: "What changes",
  styleKey: "Style key",
  scopedLook: "Scoped look",
  appliesTo: "Applies to",
  ref: "Reference",
};
// Fields already in a story piece item's title row, left out of its body.
const TITLE_FIELDS = {
  benchmark: ["work"],
  character: ["name"],
  beat: ["label", "runtimeSec"],
  scene: ["code", "place", "runtimeSec"],
};
// Pieces the user can add their own item to, and that item's fields (FILM_PIECE_ITEM_FIELDS).
const ADD_KIND = {
  logline: "benchmark",
  characters: "character",
  beats: "beat",
  scenes: "scene",
  look: "styleKey",
};
const ADD_FIELDS = {
  benchmark: ["work", "take", "avoid"],
  character: ["name", "role", "want", "flaw", "arc", "look"],
  beat: ["label", "beat", "act", "runtimeSec"],
  scene: ["code", "place", "time", "change", "runtimeSec", "script"],
  styleKey: ["styleKey", "palette", "camera", "aspect", "moodFrom"],
};
const PLUS =
  '<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M8 3v10M3 8h10" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>';
const PEN =
  '<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M10.5 2.5 13.5 5.5 5.5 13.5H2.5V10.5z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/></svg>';

function inputError(problem) {
  return new Error(
    `Invalid film card inputs: ${problem}. Pass the story JSON as inputs.piece and its file path as inputs.path, or use the inputs from voyager film card (not the whole command result).`,
  );
}

// Also check stored HTML inputs and cross-field constraints the JSON schema cannot express.
function invalidInputs(inputs) {
  const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
  const isString = (value) => typeof value === "string";
  const isText = (value) => isString(value) && value.length > 0;
  const isVersion = (value) => Number.isInteger(value) && value >= 1;
  const isStatus = (value) => Object.hasOwn(STATUS_LABEL, value);
  const isDate = (date) => /^\d{4}-\d{2}-\d{2}$/.test(String(date));
  const optional = (ok) => (value) => value === undefined || ok(value);
  const object = optional(isObject);
  const listOf = (ok) => (value) => Array.isArray(value) && value.every(ok);
  const oneOf = (list) => (value) => list.includes(value);
  const idList =
    (ok, max = Infinity) =>
    (value) =>
      listOf(ok)(value) &&
      value.length > 0 &&
      value.length <= max &&
      new Set(value.map((entry) => entry.id)).size === value.length;
  // The first key that is unlisted or fails its check.
  const fault = (value, checks) =>
    isObject(value)
      ? (Object.keys(value).find((key) => !Object.hasOwn(checks, key)) ??
        Object.keys(checks).find((key) => !checks[key](value[key])))
      : "(not an object)";
  const shape = (checks) => (value) => fault(value, checks) === undefined;
  const fields = (value) => isObject(value) && Object.values(value).every(isString);
  const names = optional(listOf(isString));
  const media = optional(listOf(isText));
  const alternatives = (items) =>
    optional(idList(shape({ id: isText, label: isText, why: optional(isString), items }), 3));
  const pieceItems = idList(
    shape({
      id: (id) => isString(id) && /^[a-z0-9-]+$/.test(id),
      kind: oneOf(KINDS),
      fields,
      media,
      userEdited: names,
    }),
  );
  const cardItems = idList(
    shape({
      id: (id) => isString(id) && /^[A-Za-z0-9][A-Za-z0-9_.-]*$/.test(id),
      kind: oneOf(CARD_KINDS),
      title: optional(isString),
      group: optional(isString),
      fields,
      readOnly: names,
      advanced: names,
      decisions: optional(listOf(oneOf(DECISIONS))),
      media,
      mediaRoles: optional(listOf((role) => Object.hasOwn(ROLE_LABEL, role))),
      cost: optional(isString),
      userEdited: names,
    }),
  );

  const top = fault(inputs, {
    piece: isObject,
    path: isText,
    next: optional(shape({ id: isString, title: isString, cost: optional(isString) })),
    history: optional(listOf(shape({ version: isVersion, status: isStatus }))),
  });
  if (top !== undefined) return `bad ${top}`;
  const piece = inputs.piece;
  const card = piece.schema === "voyager.film-piece/2";
  const key = card
    ? fault(piece, {
        schema: () => true,
        stage: (stage) => Object.hasOwn(STAGES, stage),
        id: (id) => isString(id) && /^[a-z0-9-]+$/.test(id),
        title: isText,
        status: isStatus,
        version: isVersion,
        approved: optional(isDate),
        basedOn: optional(
          (basedOn) => isObject(basedOn) && Object.values(basedOn).every(isVersion),
        ),
        summary: optional(isString),
        items: cardItems,
        alternatives: alternatives(cardItems),
        chosenAlternative: optional(isString),
      })
    : fault(piece, {
        schema: (schema) => schema === "voyager.film-piece/1",
        stage: (stage) => stage === "treatment",
        id: (id) => Object.hasOwn(PIECES, id),
        title: isText,
        // A story piece is never locked; only a stage card is.
        status: (status) => status !== "locked" && isStatus(status),
        version: isVersion,
        approved: optional(isDate),
        basedOn: (basedOn) =>
          isObject(basedOn) &&
          Object.entries(basedOn).every(
            ([id, version]) => Object.hasOwn(PIECES, id) && isVersion(version),
          ),
        summary: optional(isString),
        items: pieceItems,
        alternatives: alternatives(pieceItems),
        chosenAlternative: () => true,
        autoApproved: optional((flag) => flag === !!flag),
        types: optional(
          (types) =>
            listOf((type) => /^(narrative|commercial|viral|product)$/.test(type))(types) &&
            types.length > 0 &&
            new Set(types).size === types.length,
        ),
        typeInputs: optional(
          (inputs) =>
            shape({ commercial: object, viral: object, product: object })(inputs) &&
            Object.keys(inputs).length > 0,
        ),
      });
  if (key !== undefined) return `bad piece.${key}`;
  if (piece.id !== "logline" && (piece.types || piece.typeInputs)) return "types off logline";
  // The schema cannot say a chosen alternative must be listed.
  const chosen = piece.chosenAlternative;
  if (chosen !== undefined && piece.alternatives?.every((entry) => entry.id !== chosen))
    return "unknown chosen alternative";
  return null;
}

globalThis.filmPieceKinds = {
  PIECES,
  STAGES,
  DECISIONS,
  ROLE_LABEL,
  STATUS_LABEL,
  LABEL,
  TITLE_FIELDS,
  ADD_KIND,
  ADD_FIELDS,
  PLUS,
  PEN,
  inputError,
  invalidInputs,
};

