/* The host supplies --voyager-* tokens and a baseline; its frame is the card. */
:root {
  --ink: var(--voyager-fg);
  --quiet: var(--voyager-muted-fg);
  --line: var(--voyager-border);
  --well: var(--voyager-muted);
  --hover: color-mix(in srgb, var(--ink) 5%, transparent);
  --selected: color-mix(in srgb, var(--ink) 12%, var(--voyager-surface));
  --now: color-mix(in srgb, var(--voyager-accent) 22%, transparent);
  --cut: color-mix(in srgb, var(--quiet) 70%, transparent);
  --radius: 6px;
}
body {
  padding: 12px 14px 10px;
}
button,
input {
  font: inherit;
  color: inherit;
}
button {
  min-height: 0;
  box-shadow: none;
}
.transcript:focus-visible {
  outline: none;
}
.pane:has(.transcript:focus-visible) {
  border-color: color-mix(in srgb, var(--ink) 40%, transparent);
}
button:focus-visible,
input:focus-visible,
.track:focus-visible {
  outline: 2px solid var(--voyager-focus);
  outline-offset: 2px;
}
/* The toolbar stays in view while the card scrolls in a short frame. */
header {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 12px;
  margin: -12px -14px 0;
  padding: 12px 14px 10px;
  background: var(--voyager-bg);
}
h1 {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0;
}
.duration {
  font-size: 0.75rem;
  color: var(--quiet);
  font-variant-numeric: tabular-nums;
}
.duration b {
  color: var(--ink);
  font-weight: 600;
}
.saving {
  margin-left: 8px;
}
.saving::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  margin-right: 5px;
  border-radius: 50%;
  background: var(--quiet);
  vertical-align: 1px;
  animation: pulse 1s ease-in-out infinite;
}
@keyframes pulse {
  50% {
    opacity: 0.3;
  }
}
.tools {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-left: auto;
}
.tool {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 10px;
  font-size: 0.8125rem;
  font-weight: 500;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--voyager-surface);
}
.tool:hover:not(:disabled) {
  background: var(--hover);
}
.tool.primary {
  background: var(--ink);
  color: var(--voyager-bg);
  border-color: transparent;
}
.tool.primary:hover:not(:disabled) {
  background: color-mix(in srgb, var(--ink) 85%, var(--voyager-bg));
}
.menu-anchor {
  position: relative;
}
.menu {
  position: absolute;
  z-index: 3;
  top: calc(100% + 4px);
  left: 0;
  min-width: 220px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--voyager-surface);
  box-shadow: 0 6px 24px color-mix(in srgb, var(--ink) 14%, transparent);
}
.menu[hidden] {
  display: none;
}
.option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 4px;
  font-size: 0.8125rem;
  font-weight: 450;
  cursor: pointer;
}
.option:hover {
  background: var(--hover);
}
.option .count {
  margin-left: auto;
  color: var(--quiet);
  font-variant-numeric: tabular-nums;
}
.menu > button {
  width: 100%;
  margin-top: 6px;
  height: 28px;
  border-radius: var(--radius);
  background: var(--ink);
  color: var(--voyager-bg);
  border: 0;
  font-size: 0.8125rem;
}
.body {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 36%);
