const root = document.querySelector("#root");
const status = document.querySelector("#status");
const FALLBACK =
  "This transcript could not be shown here. Tell me which words to cut or restore, or ask me to clean up filler words, pauses or retakes.";
const REASON = {
  filler: "Filler",
  pause: "Pause",
  retake: "Retake",
  user: "You",
  agent: "Agent",
};
const {
  audible,
  cutSpans,
  editedDuration,
  paragraphs,
  ranges,
  fixRange,
  withBase,
  settleReceipt,
  fixing,
  previewTimeline,
  previewWords,
  fixVoice,
  fixRetry,
  fixDone,
  HOSTED_HINT,
  historyKey,
  editQueue,
  cleanupCounts,
  cutRun,
  editWarnings,
  clock,
} = globalThis.transcriptModel ?? {};
const {
  el,
  button,
  consentNotice,
  fixBubble,
  trackValues,
  announceSelection,
  keepInView,
  playIcon,
  pauseIcon,
  caretIcon,
  historyTools,
  voiceIcon,
  takeBar,
  suggestionBar,
  cleanupMenu,
  warningArea,
  previewFailure,
} = globalThis.transcriptUi ?? {};
// How often a visible card checks for edits made outside it (the agent's CLI, another card).
const REFRESH_MS = 2000;

let model;
let edits;
let shownRevision;
let refreshing;
let spans = [];
let timeline = { pieces: [], durationS: 0 };
let mapping;
let index = new Map();
let elements = [];
let replacementEls = new Map();
let selection;
let anchor;
let caret = 0;
let dragging = false;
let editing;
let playing = -1;
let player;
let shownPaused;
// Consents ticked here, by `fixVoice`'s consentKey; `cloneRefused` once the saved voice was refused
// for the plan (later fixes make a one-off copy, whatever a cached status says); `voiceModel` once
// "Use on this computer".
const fixState = { consented: {}, cloneRefused: false };
let stepping = false;
const ui = {};

try {
  if (!clock || !el)
    throw new Error("Missing transcript card resources. Reload Voyager and try again.");
  const inputs = (await host.context.get()).inputs ?? {};
  if (typeof inputs.project !== "string") throw new Error("This card needs a project.");
  model = await host.data
    .read("transcript", {})
    .then((snapshot) => {
      shownRevision = snapshot.revision;
      return snapshot.value;
    })
    .catch((error) => {
      if (Array.isArray(inputs.words)) return inputs;
      throw error;
    });
  if (!Array.isArray(model?.words)) throw new Error("The transcript is not ready yet.");
  edits = editQueue(model);
  mount();
  setInterval(() => {
    if (document.visibilityState === "visible") void refresh();
  }, REFRESH_MS);
  window.addEventListener("focus", () => void refresh());
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") void refresh();
  });
} catch (error) {
  root.replaceChildren(el("p", { class: "fallback" }, FALLBACK));
  say(message(error));
  host.diagnostics?.report(error);
}

function mount() {
  ui.duration = el("span", { class: "duration" });
  ui.clean = el(
    "button",
    { type: "button", class: "tool", "aria-haspopup": "menu" },
    "Clean up",
    caretIcon(),
  );
  ui.menu = el("div", { class: "menu", role: "menu", hidden: "" });
  historyTools(ui, step);
  ui.fix = el("button", { type: "button", class: "tool" }, voiceIcon(), "Fix in my voice");
  ui.export = el("button", { type: "button", class: "tool primary" }, "Export");
  ui.exported = el("span", { class: "exported" });
  // A fix the voice may have misread (Hear it / Try again) and the cuts worth listening across.
  ui.warn = warningArea({
    fix: (id) => model.words[rangeIndices(id)[0]],
    hear: (word) => player.hear(word),
    retry: (word) => replace(rangeOf(word.replacement.id), word.replacement.text),
    jump: (at) => {
      // Plays from the word before the cut, so the join is heard.
      player.seekWord(
        Math.max(
          0,
          model.words.findLastIndex((word, i) => i < at && audible(word)),
        ),
      );
      elements[at]?.scrollIntoView({ block: "center" });
      if (ui.video.paused) player.togglePlay();
    },
  });
  ui.transcript = el("div", {
    class: "transcript",
    tabindex: "0",
    role: "textbox",
    "aria-multiline": "true",
    "aria-readonly": "true",
    "aria-label": "Transcript. Select words, then press Delete to cut them.",
