  // An audio-only recording plays through the same element, behind a slim bar instead of a frame.
  ui.audio = el(
    "div",
    { class: "audio-bar", hidden: "" },
    el(
      "span",
      { class: "bars", "aria-hidden": "true" },
      el("i"),
      el("i"),
      el("i"),
      el("i"),
      el("i"),
    ),
    el("span", { class: "audio-name" }),
  );
  ui.screen = el(
    "div",
    { class: "screen" },
    ui.video,
    ui.audio,
    ui.noMedia,
    ui.updating,
    ui.failed.node,
  );
  root.replaceChildren(
    el(
      "header",
      {},
      el("h1", {}, "Edit by text"),
      ui.duration,
      ui.warn.listen,
      ui.exported,
      el(
        "div",
        { class: "tools" },
        el("div", { class: "menu-anchor" }, ui.clean, ui.menu),
        ui.undo,
        ui.redo,
        ui.fix,
        ui.export,
      ),
      ui.warn.voice,
    ),
    ui.notice,
    ui.said,
    el(
      "div",
      { class: "body" },
      el("div", { class: "pane" }, ui.transcript, ui.bubble),
      el(
        "aside",
        { class: "player" },
        ui.screen,
        el("div", { class: "controls" }, ui.play, ui.track, ui.time),
        el(
          "p",
          { class: "hint" },
          "Click a word to jump there. Select words and press Delete to cut them.",
        ),
      ),
    ),
  );
  cleanupMenu(ui, (chosen) => {
    run({ action: "clean", ...chosen });
    say("Cleaning up. Removed words stay visible, struck through.");
  });
  ui.fix.addEventListener("click", () => startFix());
  ui.export.addEventListener("click", () => exportCut());
  ui.play.addEventListener("click", () => player.togglePlay());
