// --- Transcript ----------------------------------------------------------------------------

// Builds every paragraph once; later edits only repaint the words that changed.
function build() {
  index = new Map(model.words.map((word, at) => [word.id, at]));
  elements = [];
  replacementEls = new Map();
  const names = new Map((model.speakers ?? []).map((speaker) => [speaker.id, speaker.name]));
  const takeStarts = new Map();
  (model.takes ?? []).forEach((take) => {
    const first = index.get(take.ranges[0]?.[0]);
    if (first !== undefined) takeStarts.set(first, take);
  });
  const fragment = document.createDocumentFragment();
  paragraphs(model.words).forEach((paragraph, number, list) => {
    // A speaker continuing after a pause keeps their name off the new paragraph.
    const continued = list[number - 1]?.speaker === paragraph.speaker;
    const text = el("p", { class: "words" });
    for (let at = paragraph.start; at < paragraph.end; at++) {
      const word = model.words[at];
      const take = takeStarts.get(at);
      if (take && suggested(take)) text.append(suggestionBar(take));
      else if (take && take.applied !== false) text.append(takeBar(take));
      if (word.kind !== "punct" && at !== paragraph.start) text.append(" ");
      const span = el("span", { class: "w", "data-i": String(at) }, word.text);
      elements[at] = span;
      text.append(span);
    }
    fragment.append(
      el(
        "section",
        { class: "para" },
        el(
          "div",
          { class: "who" },
          continued ? "" : el("b", {}, names.get(paragraph.speaker) ?? paragraph.speaker ?? ""),
          el(
            "button",
            {
              type: "button",
              class: "stamp",
              "data-seek": String(paragraph.start),
              tabindex: "-1",
            },
            clock(model.words[paragraph.start].startS),
          ),
        ),
        text,
      ),
    );
  });
  ui.transcript.replaceChildren(fragment);
  paint();
}

// A retake the backend found but didn't cut (a complete sentence said again later): a suggestion.
function suggested(take) {
  return take.applied === false && !take.dismissed;
}

function paint() {
  spans = cutSpans(model);
  timeline = previewTimeline(model, spans);
  mapping = previewWords(model, timeline);
  const kept = new Set();
  (model.takes ?? []).forEach((take) => {
    if (take.applied === false) return;
    const range = take.ranges[take.keep];
    const start = index.get(range?.[0]);
    const end = index.get(range?.[1]);
    if (start !== undefined && end !== undefined)
      for (let at = start; at <= end; at++) kept.add(at);
    ui.transcript.querySelectorAll(`.take[data-take="${take.id}"]`).forEach((chip) => {
      chip.setAttribute("aria-pressed", String(Number(chip.dataset.keep) === take.keep));
    });
  });
  const seen = new Set();
  model.words.forEach((word, at) => {
    const span = elements[at];
    if (!span) return;
    const selected = selection && at >= selection[0] && at <= selection[1];
    const replaced = word.state === "replaced" && word.replacement;
    const name = [
      "w",
      word.state === "removed" ? "cut" : "",
      replaced ? "gone" : "",
      word.kind === "filler" ? "filler" : "",
      kept.has(at) ? "kept-take" : "",
      selected ? "sel" : "",
      at === playing ? "now" : "",
    ]
      .filter(Boolean)
      .join(" ");
    if (span.className !== name) span.className = name;
    const reason = word.state === "removed" ? (REASON[word.reason] ?? "") : "";
    if ((span.dataset.reason ?? "") !== reason) {
      if (reason) span.dataset.reason = reason;
      else delete span.dataset.reason;
    }
    if (replaced && !seen.has(word.replacement.id)) {
      seen.add(word.replacement.id);
      placeReplacement(word, at);
    }
  });
  replacementEls.forEach((node, id) => {
    if (!seen.has(id)) {
      node.remove();
      replacementEls.delete(id);
    }
  });
  const counts = cleanupCounts(model, spans);
  const exact = model.duration?.editedS;
  const edited = !edits.pending && typeof exact === "number" ? exact : editedDuration(model, spans);
  ui.duration.replaceChildren(
    el("b", {}, clock(edited)),
    ` of ${clock(model.duration?.sourceS ?? edited)}`,
    edits.pending ? el("span", { class: "saving" }, "Saving") : "",
  );
  ui.undo.disabled = !model.canUndo || fixing(model);
  ui.redo.disabled = !model.canRedo || fixing(model);
  ui.menuCounts = counts;
  ui.fix.disabled = !selectionWords().some((word) => word.kind !== "punct");
  renderBubble();
  drawTrack();
  ui.failed.show(model);
}

// The typed words, shown once before the run they replace, underlined as AI voice.
function placeReplacement(word, at) {
  const replacement = word.replacement;
  const existing = replacementEls.get(replacement.id);
  const label = `${replacement.text}`;
  if (existing && existing.dataset.text === label && existing.nextSibling === elements[at]) return;
  existing?.remove();
  const node = el(
    "span",
    {
      class: "fixed",
      "data-replacement": replacement.id,
      "data-text": label,
      "data-i": String(at),
      title: `AI voice. Was: ${originalText(replacement.id)}`,
    },
    el("span", { class: "fixed-text" }, label),
    el("span", { class: "ai" }, "AI voice"),
  );
  elements[at].before(node);
  replacementEls.set(replacement.id, node);
}

function originalText(replacementId) {
  return model.words
    .filter((word) => word.replacement?.id === replacementId)
    .map((word) => word.text)
    .join(" ");
}

function wireTranscript() {
  const pane = ui.transcript;
  pane.addEventListener("pointerdown", (event) => {
    const chip = event.target.closest(".take");
    if (chip) return;
    const stamp = event.target.closest(".stamp");
    if (stamp) {
      player.seekWord(Number(stamp.dataset.seek));
      return;
    }
    const at = wordIndex(event.target);
    if (at === undefined) {
      if (!event.target.closest(".bubble")) select(undefined);
      return;
    }
    event.preventDefault();
    pane.focus({ preventScroll: true });
    if (event.shiftKey && anchor !== undefined) select([anchor, at]);
    else {
      anchor = at;
      select([at, at]);
      dragging = true;
    }
    caret = at;
  });
  pane.addEventListener("pointerover", (event) => {
    if (!dragging) return;
    const at = wordIndex(event.target);
    if (at !== undefined) {
      caret = at;
      select([anchor, at]);
    }
  });
  window.addEventListener("pointerup", (event) => {
    if (!dragging) return;
    dragging = false;
    renderBubble();
    // A plain click (no drag) also moves the playhead to that word.
    if (selection && selection[0] === selection[1] && wordIndex(event.target) === selection[0])
      player.seekWord(selection[0]);
  });
  pane.addEventListener("click", (event) => {
    const chip = event.target.closest(".take");
    const id = chip?.dataset.take;
    // Dismissed in the project, so a reload or the next Clean up doesn't offer it again.
    if (chip?.classList.contains("dismiss"))
      run({ action: "dismiss", id }, (draft) => {
        draft.takes = draft.takes.filter((take) => take.id !== id);
      });
    else if (chip) keepTake(id, Number(chip.dataset.keep));
  });
  // Keys on a chip inside the pane (Take 2, Accept) are the chip's own.
  pane.addEventListener("keydown", (event) => {
    if (editing || event.target !== pane) return;
    if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault();
      cutSelection();
    } else if (event.key === "Escape") select(undefined);
    else if (event.key === " ") {
      event.preventDefault();
      player.togglePlay();
    } else if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
      event.preventDefault();
      const step = event.key === "ArrowRight" ? 1 : -1;
      const base = selection ? (step > 0 ? selection[1] : selection[0]) : caret;
      caret = Math.max(0, Math.min(model.words.length - 1, (event.shiftKey ? caret : base) + step));
      if (event.shiftKey) {
        if (anchor === undefined) anchor = base;
        select([anchor, caret]);
      } else {
        anchor = caret;
        select([caret, caret]);
      }
      elements[caret]?.scrollIntoView({ block: "nearest" });
    }
  });
  document.addEventListener("keydown", (event) => {
    const kind = !editing && historyKey(event);
    if (!kind) return;
    event.preventDefault();
    step(kind);
  });
}

function wordIndex(target) {
  const node = target.closest?.("[data-i]");
  return node ? Number(node.dataset.i) : undefined;
}

// Only the words entering or leaving the selection repaint, so dragging stays smooth on a long
// recording.
function select(range) {
  const previous = selection;
  selection = range ? [Math.min(...range), Math.max(...range)] : undefined;
  if (!range) anchor = undefined;
  if (editing && !range) closeFix();
  mark(previous, false);
  mark(selection, true);
  ui.fix.disabled = !selectionWords().some((word) => word.kind !== "punct");
  announceSelection(ui.said, selectionWords());
  renderBubble();
}

function mark(range, on) {
  if (!range) return;
  for (let at = range[0]; at <= range[1]; at++) elements[at]?.classList.toggle("sel", on);
}

function selectionWords() {
  return selection ? model.words.slice(selection[0], selection[1] + 1) : [];
}

function selectionIndices(predicate) {
  if (!selection) return [];
  const list = [];
  for (let at = selection[0]; at <= selection[1]; at++)
    if (predicate(model.words[at])) list.push(at);
  return list;
}

// --- Selection bubble ------------------------------------------------------------------------

function renderBubble() {
  const bubble = ui.bubble;
  if (!selection || dragging || editing) {
    if (!editing) bubble.hidden = true;
    return;
  }
  const words = selectionWords();
  const live = words.filter((word) => audible(word) && word.state !== "replaced");
  const removed = words.filter((word) => word.state === "removed");
  const fixed = words.find((word) => word.state === "replaced");
  const buttons = [];
  if (fixed) {
    buttons.push(button("Hear it", () => player.hear(fixed)));
    buttons.push(
      button("Try again", () => replace(rangeOf(fixed.replacement.id), fixed.replacement.text)),
    );
    buttons.push(button("Undo fix", () => restoreIndices(rangeIndices(fixed.replacement.id))));
  }
  if (live.length)
    buttons.push(
      button(`Delete${live.length > 1 ? ` ${live.length} words` : ""}`, cutSelection, "danger"),
    );
  if (removed.length)
    buttons.push(
      // One struck word restores the whole cut it is in; a range restores exactly the range.
      button("Restore", () =>
        restoreIndices(
          selection[0] === selection[1]
            ? cutRun(model.words, selection[0])
            : selectionIndices((word) => word.state === "removed"),
        ),
      ),
    );
  if (live.length && !fixed) buttons.push(button("Fix in my voice", startFix));
  if (!buttons.length) {
    bubble.hidden = true;
    return;
  }
  bubble.replaceChildren(...buttons);
  bubble.hidden = false;
  positionBubble();
}

function positionBubble() {
  const target = elements[selection[1]];
  if (!target) return;
  const pane = ui.transcript.getBoundingClientRect();
  const rect = (
    replacementEls.get(model.words[selection[1]].replacement?.id) ?? target
  ).getBoundingClientRect();
  const parent = ui.bubble.offsetParent?.getBoundingClientRect() ?? pane;
  const top = rect.bottom - parent.top + 6;
  const visible = rect.bottom > pane.top && rect.top < pane.bottom;
  ui.bubble.style.visibility = visible ? "visible" : "hidden";
  ui.bubble.style.top = `${top}px`;
  ui.bubble.style.left = `${Math.max(4, Math.min(rect.left - parent.left, parent.width - ui.bubble.offsetWidth - 4))}px`;
}

// --- Edits -----------------------------------------------------------------------------------

function cutSelection() {
  const targets = selectionIndices((word) => audible(word) && word.state !== "replaced");
  if (!targets.length) return;
  const words = ranges(model.words, targets);
  run({ action: "cut", words, reason: "user" }, (draft) => {
    targets.forEach((at) => {
      draft.words[at] = { ...draft.words[at], state: "removed", reason: "user" };
    });
  });
  say(`Cut ${targets.length} word${targets.length === 1 ? "" : "s"}.`);
}

// One undo or redo at a time, none while a fix runs.
function step(kind) {
  if (stepping || fixing(model) || !model[kind === "undo" ? "canUndo" : "canRedo"]) return;
  stepping = true;
  void run({ action: kind })
    .then((result) => {
      if (result) say(kind === "undo" ? "Undone." : "Redone.");
    })
    .finally(() => {
      stepping = false;
    });
}

function restoreIndices(targets) {
  if (!targets.length) return;
  run({ action: "restore", words: ranges(model.words, targets) }, (draft) => {
    targets.forEach((at) => {
      draft.words[at] = { ...draft.words[at], state: "kept", reason: null, replacement: undefined };
    });
  });
}

function keepTake(takeId, keep) {
  const take = (model.takes ?? []).find((entry) => entry.id === takeId);
  // Accepting a suggestion sends its own keep, which then cuts the other takes.
  if (!take || (take.keep === keep && take.applied !== false)) return;
  run({ action: "take", take: takeId, keep }, (draft) => {
    draft.takes = draft.takes.map((entry) =>
      entry.id === takeId ? { ...entry, keep, applied: true } : entry,
    );
    take.ranges.forEach(([first, last], number) => {
      const start = index.get(first);
      const end = index.get(last);
      for (let at = start; at <= end; at++) {
        const word = draft.words[at];
        if (number === keep) draft.words[at] = { ...word, state: "kept", reason: null };
        else if (word.state !== "removed")
          draft.words[at] = { ...word, state: "removed", reason: "retake" };
      }
    });
  });
}

// --- Fix in my voice -------------------------------------------------------------------------

function startFix() {
  if (!selection) return;
  const range = fixRange(model.words, selection[0], selection[1]);
  if (range.error) return say(range.error);
  const { first, last } = range;
  const original = model.words
    .slice(first, last + 1)
    .map((word) => word.text)
    .join(" ")
    .replace(/ ([,.?!;:])/g, "$1");
  const voice = fixVoice(model.voice, fixState);
  const bubble = fixBubble(original, voice, {
    cancel: closeFix,
    apply: (text) => {
      // One request per click: the consent rides on the fix (the host spends the activation once).
      if (voice.needsConsent) fixState.consented[voice.consentKey] = true;
      closeFix();
      replace(range.ref, text, voice.needsConsent, voice);
    },
    forget: () => {
      closeFix();
      fixState.consented = {};
      void run({ action: "consent", local: false, hosted: false }).then((result) => {
        if (result) say("Your saved voice for this project is forgotten.");
      });
    },
  });
  editing = { first, last };
  ui.bubble.replaceChildren(bubble.node);
  ui.bubble.hidden = false;
  positionBubble();
  bubble.input.focus();
  bubble.input.select();
}

function closeFix() {
  editing = undefined;
  ui.bubble.hidden = true;
  ui.transcript.focus({ preventScroll: true });
  paint();
}

// `shown`: the bubble's voice; consent is for it.
function replace(words, text, consent = false, shown = undefined) {
  const [first, last] = String(words)
    .split("..")
    .map((id) => index.get(id));
  const end = last ?? first;
  const id = `pending-${Date.now()}`;
  const voice = shown ?? fixVoice(model.voice, fixState);
  const payload = {
    action: "replace",
    words,
    text,
    voice: fixState.cloneRefused ? "local" : "auto",
    ...(voice.voiceModel ? { voiceModel: voice.voiceModel } : {}),
    ...(consent ? { consent: true } : {}),
  };
  say("Making the new words in your voice…");
  notice();
  ui.warn.voice.hidden = true;
  const slow = voice.setup ? setTimeout(() => say(voice.setup), 8000) : undefined;
  // Its words show pending while it (or a retry) runs, so Undo waits.
  const mark = (draft) => {
    for (let at = first; at <= end; at++)
      draft.words[at] = {
        ...draft.words[at],
        state: "replaced",
        reason: null,
        replacement: { id, text, voice: "local" },
      };
  };
  // A failed fix can be retried (`fixRetry`); consent asked here is for the model it names.
  const retry = (code, text, sent) => {
    const next = fixRetry(code, sent, text, {
      hosted: voice.model?.hosted,
      voiceModel: fixVoice(model.voice, { ...fixState, cloneRefused: true }).voiceModel,
      localConsent: model.voice?.localConsent || !!fixState.consented.local,
    });
    if (!next) return;
    const again = (voiceModel) => {
      const sent = voiceModel ? { ...next.payload, voiceModel } : next.payload;
      notice();
      void run(sent, mark, (nextCode, nextText) => retry(nextCode, nextText, sent)).then(fixed);
    };
    const ask = () => {
      const now = fixVoice(
        model.voice,
        next.local ? { ...fixState, voiceModel: next.payload.voiceModel } : fixState,
      );
      consentNotice(
        ui.notice,
        next.local ? now.text : `${text} ${now.text}`,
        () => {
          fixState.consented[now.consentKey] = true;
          again(now.voiceModel);
        },
        next.local ? undefined : next.label,
      );
    };
    if (next.local)
      return notice(next.message, next.label, () => {
        fixState.voiceModel = next.payload.voiceModel;
        if (next.consent) ask();
        else again();
      });
    if (next.consent) {
      fixState.cloneRefused = true;
      return ask();
    }
    notice(next.message, next.label, () => again());
  };
  void run(payload, mark, (code, failed) => retry(code, failed, payload)).then((result) => {
    clearTimeout(slow);
    fixed(result);
  });
}

function fixed(result) {
  if (result) say(fixDone());
  if (result?.hostedNote) notice(HOSTED_HINT, "Got it", notice);
}

// A message above the transcript that needs the user, with one action; no arguments hides it.
function notice(text, label, action) {
  ui.notice.hidden = !text;
  ui.notice.replaceChildren(...(text ? [el("span", {}, text)] : []));
  if (label) ui.notice.append(button(label, action));
}

function rangeIndices(replacementId) {
  return model.words.flatMap((word, at) => (word.replacement?.id === replacementId ? [at] : []));
}

function rangeOf(replacementId) {
  return ranges(model.words, rangeIndices(replacementId))[0];
}

async function exportCut() {
  ui.export.disabled = true;
  say("Exporting the edited video…");
  ui.exported.textContent = "Exporting…";
  const result = await run({ action: "export" });
  ui.export.disabled = false;
  ui.exported.textContent = "";
  const files = [result?.mp4, result?.srt, result?.path].filter(
    (value) => typeof value === "string",
  );
  if (!files.length) return;
  say(`Exported: ${files.join(", ")}`);
  ui.exported.textContent = `Exported ${files.map((file) => file.split(/[\\/]/).at(-1)).join(", ")}`;
  ui.exported.title = files.join("\n");
}

// Shows the edit at once on top of the last authoritative card; the server's card replaces it.
// On a failure the card refetches the project instead of restoring an older snapshot: a later
// edit may already have succeeded, and a failed edit may still have changed something.
function run(payload, optimistic, onFailure) {
  const sent = withBase(payload, edits);
  const id = edits.begin(optimistic);
  selection = undefined;
  update();
  // The host needs the click's activation, so the request leaves now; the server orders them.
  return host.actions
    .invoke("edit", sent, { requestKey: crypto.randomUUID() })
    .then((receipt) => settleReceipt(host.receipts, receipt))
    .then((receipt) => {
      if (receipt.status !== "completed")
        throw Object.assign(new Error(receipt.error ?? `The edit was ${receipt.status}.`), {
          outcomeUnknown: receipt.status === "outcome_unknown",
        });
      const card =
        receipt.result?.card ?? (Array.isArray(receipt.result?.words) ? receipt.result : undefined);
      edits.settle(id, card);
      ui.warn.show(editWarnings(edits.committed, receipt.result?.changed?.warnings));
      // A saved edit whose card couldn't be built (or an export) is read back from the project.
      if (!card) void refresh(true);
      return receipt.result;
    })
    .catch(async (error) => {
      edits.settle(id);
      const rev = edits.committed.rev;
      await refresh(true);
      // The host puts the error's code first, e.g. "LOCAL_VOICE_INSTALL_FAILED: …".
      const [, code, text] = /^([A-Z][A-Z_]+): ([\s\S]*)$/.exec(message(error)) ?? [
        "",
        undefined,
        message(error),
      ];
      // An edit that may have been saved isn't offered again: the refreshed card shows whether
      // it happened (an Undo tried twice would undo two edits).
      if (code === "OUTCOME_UNKNOWN" || error?.outcomeUnknown) {
        say(
          edits.committed.rev !== rev
            ? "That edit went through. The card shows the project as saved."
            : "That edit may not have gone through. The card shows the project as saved; check it before trying again.",
        );
        return undefined;
      }
      // Changed elsewhere (the agent, another card) since the card showed it: now refreshed.
      if (code === "STALE_REV")
        return notice(
          "The transcript changed since you last saw it. The card now shows the latest; try again.",
          "OK",
          notice,
        );
      say(
        edits.committed.rev !== rev
          ? `${text} The card was refreshed with the latest edits.`
          : text,
      );
      onFailure?.(code, text);
      return undefined;
    })
    .finally(() => update());
}

// Reads the project again; adopts it when it changed (an agent's CLI edit, another card, a
// finished preview). Edits still in flight stay shown on top.
async function refresh(force = false) {
  if (refreshing) return refreshing;
  refreshing = host.data
    .read("transcript", {})
    .then((snapshot) => {
      if (!force && snapshot.revision && snapshot.revision === shownRevision) return;
      if (edits.commit(snapshot.value)) {
        shownRevision = snapshot.revision;
        update();
      }
    })
    .catch(() => undefined)
    .finally(() => {
      refreshing = undefined;
    });
  return refreshing;
}

// Shows the current view: the committed card plus edits in flight.
function update() {
  const card = edits.view();
  const sameWords =
    card.words.length === model.words.length &&
    card.words.every((word, at) => word.id === model.words[at].id);
  const sameTakes =
    JSON.stringify(
      (card.takes ?? []).map((take) => [take.ranges, take.applied, take.dismissed]),
    ) ===
    JSON.stringify((model.takes ?? []).map((take) => [take.ranges, take.applied, take.dismissed]));
  const mediaChanged =
    card.media?.[0]?.path !== model.media?.[0]?.path ||
    player.playable(card) !== player.playable(model) ||
    card.preview?.failed !== model.preview?.failed ||
    card.rev !== model.rev;
  model = card;
  if (!sameWords || !sameTakes) build();
  else paint();
  if (mediaChanged) void player.loadMedia();
}

// --- Player (player.js) -------------------------------------------------------------------

function tick() {
  player.follow();
  const at = player.currentWord();
  if (at !== playing) {
    elements[playing]?.classList.remove("now");
    playing = at;
    const node = elements[at];
    node?.classList.add("now");
    if (node && !ui.video.paused && !selection) keepInView(ui.transcript, node);
  }
  drawTrack();
  requestAnimationFrame(tick);
}

function drawTrack() {
  if (!ui.track) return;
  const total = player.totalEdited();
  const now = player.currentEdited();
  ui.track.firstChild.style.width = `${total ? Math.min(100, (now / total) * 100) : 0}%`;
  const label = `${clock(now)} / ${clock(total)}`;
  if (ui.time.textContent !== label) {
    ui.time.textContent = label;
    trackValues(ui.track, now, total, label);
  }
  if (shownPaused === ui.video.paused) return;
  shownPaused = ui.video.paused;
  ui.screen.classList.toggle("playing", !shownPaused);
  ui.play.replaceChildren(shownPaused ? playIcon() : pauseIcon());
  ui.play.setAttribute("aria-label", shownPaused ? "Play" : "Pause");
}

// --- Helpers ---------------------------------------------------------------------------------

function say(text) {
  status.textContent = text;
}

function message(error) {
  return error instanceof Error ? error.message : String(error);
}

// The card model's arithmetic, kept apart from the page so it reads on its own: which words play,
// where the edited cut skips the source, how long it runs, and how words group into paragraphs.

const AUDIBLE = new Set(["kept", "replaced"]);
// A new paragraph after this much silence, or at a sentence end once a paragraph runs long.
const PARAGRAPH_GAP_S = 2.5;
const PARAGRAPH_WORDS = 70;

function audible(word) {
  return AUDIBLE.has(word.state);
}

// Source spans the edited cut leaves out, sorted and merged: each run of removed words, plus the
// part of a long pause beyond the limit when pauses were tightened (the pause stays centred).
function cutSpans(model) {
  const words = model.words;
  const maxS = model.pauses?.maxMs > 0 ? model.pauses.maxMs / 1000 : undefined;
  const spans = [];
  let runStart = -1;
  words.forEach((word, index) => {
    if (!audible(word)) {
      if (runStart < 0) runStart = index;
      return;
    }
    if (runStart >= 0) {
      spans.push([words[runStart].startS, words[index - 1].endS]);
      runStart = -1;
    }
  });
  if (runStart >= 0) spans.push([words[runStart].startS, words.at(-1).endS]);
  if (maxS !== undefined) {
    const playing = words.filter((word) => audible(word) && word.kind !== "punct");
    playing.slice(1).forEach((word, index) => {
      const previous = playing[index];
      const gap = word.startS - previous.endS;
      if (gap > maxS) spans.push([previous.endS + maxS / 2, word.startS - maxS / 2]);
    });
  }
  spans.sort((a, b) => a[0] - b[0]);
  return spans.reduce((merged, span) => {
    const last = merged.at(-1);
    if (last && span[0] <= last[1] + 0.01) last[1] = Math.max(last[1], span[1]);
    else merged.push([...span]);
    return merged;
  }, []);
}

// Source time to edited time: the source time less every cut before it. Inside a cut, the cut's
// start, where the edited cut resumes.
function editedTime(spans, sourceS) {
  return spans.reduce((time, [start, end]) => {
    if (sourceS >= end) return time - (end - start);
    if (sourceS > start) return time - (sourceS - start);
    return time;
  }, sourceS);
}

function sourceTime(spans, editedS) {
  return spans.reduce(
    (time, [start, end]) => (time >= start ? time + (end - start) : time),
    editedS,
  );
}

// The cut that contains this source time, if any (with a small lead so playback skips cleanly).
function cutAt(spans, sourceS, leadS = 0.02) {
  return spans.find(([start, end]) => sourceS >= start - leadS && sourceS < end);
}

function editedDuration(model, spans) {
  return editedTime(spans, sourceDuration(model));
}

// The index of the word playing at this source time: the last one starting at or before it.
function wordAt(words, sourceS) {
  let low = 0;
  let high = words.length - 1;
  let found = -1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    if (words[middle].startS <= sourceS) {
      found = middle;
      low = middle + 1;
    } else high = middle - 1;
  }
  return found >= 0 && sourceS <= words[found].endS + 0.25 ? found : -1;
}

// Consecutive words of one speaker, broken at long silences and, once long, at a sentence end.
function paragraphs(words) {
  return words.reduce((list, word, index) => {
    const current = list.at(-1);
    const previous = words[index - 1];
    const sentenceEnd = previous && /[.?!]$/.test(previous.text);
    const fresh =
      !current ||
      word.speaker !== current.speaker ||
      word.startS - previous.endS > PARAGRAPH_GAP_S ||
      (current.end - current.start >= PARAGRAPH_WORDS && sentenceEnd);
    if (fresh) list.push({ speaker: word.speaker, start: index, end: index + 1 });
    else current.end = index + 1;
    return list;
  }, []);
}

// "w1..w4" for each run of consecutive indices; the CLI's --words form.
function ranges(words, indices) {
  const sorted = [...new Set(indices)].sort((a, b) => a - b);
  return sorted
    .reduce((runs, index) => {
      const last = runs.at(-1);
      if (last && index === last[1] + 1) last[1] = index;
      else runs.push([index, index]);
      return runs;
    }, [])
    .map(([start, end]) =>
      start === end ? words[start].id : `${words[start].id}..${words[end].id}`,
    );
}

// One contiguous selection as a single ref, every word from the first to the last.
function rangeRef(words, first, last) {
  return first === last ? words[first].id : `${words[first].id}..${words[last].id}`;
}

// What a fix of the selected words [first, last] replaces: exactly the words heard there, first to
// last, as one ref. A cut or already fixed word between them refuses it (`error`) rather than
// widening the fix over words the user doesn't hear or narrowing it to one side.
function fixRange(words, first, last) {
  const live = (word) => audible(word) && word.state !== "replaced";
  const heard = [];
  for (let at = first; at <= last; at++)
    if (live(words[at]) && words[at].kind !== "punct") heard.push(at);
  if (!heard.length) return { error: "Select words that play to fix them." };
  const start = heard[0];
  const end = heard.at(-1);
  for (let at = start; at <= end; at++)
    if (!live(words[at]))
      return {
        error:
          "A fix replaces one run of words you hear. Select words without cut or fixed words between them.",
      };
  return { first: start, last: end, ref: rangeRef(words, start, end) };
}

// The edits that apply to the transcript the user saw: they carry the rev the card shows
// (`baseRev`), and a project that has moved on refuses them (STALE_REV). Only while none of the
// card's own edits are in flight: those land in the order sent, each moving the rev on.
const REV_ACTIONS = new Set([
  "cut",
  "restore",
  "clean",
  "take",
  "replace",
  "dismiss",
  "undo",
  "redo",
]);
function withBase(payload, queue) {
  const rev = queue.committed.rev;
  return REV_ACTIONS.has(payload.action) && !queue.pending && typeof rev === "number"
    ? { ...payload, baseRev: rev }
    : payload;
}

const SETTLED = new Set([
  "completed",
  "failed",
  "held",
  "cancelled",
  "outcome_unknown",
  "destination_required",
]);
// Follows a card request's receipt until it settles. An export or voice fix stays `processing`
// while the server runs it beside other cards' actions: a first local fix downloads gigabytes and
// can take an hour, so the card keeps following it (less often after the first minute).
async function settleReceipt(receipts, receipt) {
  let current = receipt;
  const started = Date.now();
  while (!SETTLED.has(current.status)) {
    if (Date.now() - started > 3 * 3600_000)
      throw new Error("The edit is taking too long. Ask in the chat.");
    await new Promise((resolve) => setTimeout(resolve, Date.now() - started > 60_000 ? 1000 : 200));
    current = await receipts.get(current.id);
  }
  return current;
}

// A voice fix made from this card is still running: Undo would undo the edit before it.
const fixing = (model) =>
  model.words.some((word) => String(word.replacement?.id).startsWith("pending-"));

// The edited cut as the rendered preview plays it: source pieces in order, each
// [sourceStart, sourceEnd, editedStart], where a fix longer than its words adds a held piece
// (sourceStart === sourceEnd) after them and a shorter one trims their end. A fix's length is its
// `durationS`; without one, what the engine's edited duration leaves over is shared among them.
function previewTimeline(model, spans = cutSpans(model)) {
  const total = sourceDuration(model);
  const fixes = fixRuns(model);
  const known = fixes.reduce((sum, fix) => sum + (fix.durationS ?? fix.spokenS), 0);
  const unknown = fixes.filter((fix) => fix.durationS === undefined);
  const spare =
    unknown.length && typeof model.duration?.editedS === "number"
      ? (model.duration.editedS -
          (editedTime(spans, total) - fixes.reduce((sum, fix) => sum + fix.spokenS, 0) + known)) /
        unknown.length
      : 0;
  const changes = fixes.map((fix) => ({
    atS: fix.endS,
    deltaS: (fix.durationS ?? fix.spokenS + spare) - fix.spokenS,
  }));
  const cuts = [
    ...spans,
    ...changes
      .filter((change) => change.deltaS < 0)
      .map((change) => [change.atS + change.deltaS, change.atS]),
  ]
    .sort((a, b) => a[0] - b[0])
    .reduce((merged, span) => {
      const last = merged.at(-1);
      if (last && span[0] <= last[1]) last[1] = Math.max(last[1], span[1]);
      else merged.push([...span]);
      return merged;
    }, []);
  const holds = changes.filter((change) => change.deltaS > 0).sort((a, b) => a.atS - b.atS);
  const pieces = [];
  let edited = 0;
  const keep = (from, to) => {
    if (to <= from) return;
    pieces.push([from, to, edited]);
    edited += to - from;
  };
  let cursor = 0;
  [...cuts, [total, total]].forEach(([start, end]) => {
    holds
      .filter((hold) => hold.atS > cursor && hold.atS <= start)
      .forEach((hold) => {
        keep(cursor, hold.atS);
        pieces.push([hold.atS, hold.atS, edited, hold.deltaS]);
        edited += hold.deltaS;
        cursor = hold.atS;
      });
    keep(cursor, start);
    cursor = Math.max(cursor, end);
  });
  return { pieces, durationS: edited };
}

// Source time to preview time, and back; inside a cut, where the preview resumes, and inside a
// held picture, the end of the fixed words.
function previewTime(timeline, sourceS) {
  const piece = timeline.pieces.find(
    ([start, end]) => sourceS < end || (start === end && sourceS === start),
  );
  if (!piece) return timeline.durationS;
  return piece[2] + Math.max(0, sourceS - piece[0]);
}

function previewSource(timeline, editedS) {
  const piece = timeline.pieces.findLast(([, , start]) => start <= editedS);
  if (!piece) return 0;
  return piece[0] === piece[1] ? piece[0] : Math.min(piece[1], piece[0] + (editedS - piece[2]));
}

// The rendered preview the card can play: the finished preview of this revision, or while a newer
// one renders, the last finished one (`ready:false`, an older `rev`), played with its own mapping.
function playablePreview(model) {
  const preview = model.preview;
  if (preview?.kind !== "file" || typeof preview.path !== "string") return undefined;
  if (preview.rev === model.rev && preview.ready === false) return undefined;
  return previewWords(model) ? preview : undefined;
}

// True when the preview playing is the finished one of this revision.
function previewCurrent(model) {
  return model.preview?.rev === model.rev && model.preview?.ready !== false;
}

// Where each word plays in the rendered preview, in play order: {at, startS, endS} in edited
// time, `at` the word's index in this model. The preview's own per-word times (`preview.words`)
// first; for this revision's preview, the backend's edited word times, else the card's
// reconstruction. Undefined for an older preview that has no mapping of its own.
function previewWords(model, timeline) {
  const index = new Map(model.words.map((word, at) => [word.id, at]));
  const own = editedEntries(model.preview?.words, index);
  if (own) return own;
  if (model.preview?.rev !== model.rev) return undefined;
  const backend = editedEntries(model.words, index);
  if (backend) return backend;
  const built = timeline ?? previewTimeline(model);
  return model.words.flatMap((word, at) =>
    audible(word)
      ? [{ at, startS: previewTime(built, word.startS), endS: previewTime(built, word.endS) }]
      : [],
  );
}

// `[{id, editedStartS, editedEndS}]` (or the same keyed by id) as sorted entries; removed words
// (null times) and words this model doesn't have are left out.
function editedEntries(list, index) {
  const items = Array.isArray(list)
    ? list
    : list && typeof list === "object"
      ? Object.entries(list).map(([id, times]) => ({ id, ...times }))
      : [];
  const entries = items
    .filter(
      (item) =>
        index.has(item?.id) &&
        typeof item.editedStartS === "number" &&
        typeof item.editedEndS === "number",
    )
    .map((item) => ({ at: index.get(item.id), startS: item.editedStartS, endS: item.editedEndS }))
    .sort((a, b) => a.startS - b.startS || a.at - b.at);
  return entries.length ? entries : undefined;
}

// The word playing at this preview time (the last one starting at or before it), or -1.
function previewWordAt(entries, editedS) {
  let low = 0;
  let high = entries.length - 1;
  let found = -1;
  while (low <= high) {
    const middle = (low + high) >> 1;
    if (entries[middle].startS <= editedS) {
      found = middle;
      low = middle + 1;
    } else high = middle - 1;
  }
  return found >= 0 && editedS <= entries[found].endS + 0.25 ? entries[found].at : -1;
}

// Where a word starts in the preview; a word the preview leaves out seeks to the next one heard.
function previewSeek(entries, at) {
  const exact = entries.find((entry) => entry.at === at);
  if (exact) return exact.startS;
  const next = entries
    .filter((entry) => entry.at > at)
    .reduce((best, entry) => (!best || entry.at < best.at ? entry : best), undefined);
  return next?.startS ?? entries.at(-1)?.endS ?? 0;
}

// The model the card falls back to on this computer: Free plans, and "Use on this computer".
const LOCAL_VOICE = "qwen3-tts-0.6b-local";

// The voice a fix will use, what the fix bubble says about it, and whether it needs the consent
// tick. `state` is the card's: consents given here (`consentKey`: "local" covers every model on
// this computer, a hosted one is per model), a saved voice the plan refused, and a model chosen
// after a refusal. A hosted choice the account can't use is made on this computer, said before the
// click. The fix always names `voiceModel`, so consent is for the model shown, whatever Settings
// says by the time it runs. `setup` is what to say while a first fix sets something up.
function fixVoice(voice, state) {
  const forgettable = voice?.forgettable === true;
  if (voice?.savedClone?.available && !state.cloneRefused)
    return { text: "In your saved voice.", needsConsent: false, forgettable };
  const chosen = state.voiceModel
    ? localVoice(voice, state.voiceModel)
    : (voice?.model ?? localVoice(voice, LOCAL_VOICE));
  const refused = chosen.hosted && voice?.hostedAllowed === false;
  const model = refused ? localVoice(voice, LOCAL_VOICE) : chosen;
  const local = voice?.localModels?.find((entry) => entry.id === model.id);
  const download =
    local?.status !== "installed" && (local !== undefined || voice?.localAvailable === false);
  const size = local?.sizeBytes ? ` (about ${Math.round(local.sizeBytes / 1e9)} GB)` : "";
  const text = model.hosted
    ? `A copy of this speaker's voice, made with ${model.label}. ${
        model.id === "chatterbox-hosted"
          ? "A short clip of this speaker is sent to fal for each fix."
          : "A short clip of this speaker is sent to fal to make the fix; their voice is saved in this project for later fixes. You can forget it any time."
      }`
    : local?.installable === false
      ? "Voice fixes on this computer need an Apple Silicon Mac, Linux x64 or Windows x64."
      : download
        ? `A copy of this speaker's voice, made on this computer with ${model.label}, needs a one-time download${size}. The clip never leaves this computer.`
        : `A copy of this speaker's voice, made on this computer with ${model.label}. The clip never leaves this computer.`;
  const consentKey = model.hosted ? model.id : "local";
  const why =
    voice?.hostedReason === "signed_out"
      ? `${chosen.label} needs you signed in to Voyager, so this fix is made here.`
      : `${chosen.label} runs on paid plans, so this fix is made here.`;
  return {
    model,
    voiceModel: model.id,
    consentKey,
    forgettable,
    needsConsent: !(
      (model.hosted ? voice?.hostedConsent : voice?.localConsent) || state.consented[consentKey]
    ),
    text: refused ? `${why} ${text}` : text,
    setup: model.hosted
      ? voice?.alignmentReady === false
        ? "Preparing the word check (one time, about 75 MB)…"
        : undefined
      : "Setting up the voice on this computer. The first time takes a few minutes…",
  };
}

function localVoice(voice, id) {
  const found = voice?.localModels?.find((entry) => entry.id === id);
  return {
    id,
    label: found?.label ?? (id === LOCAL_VOICE ? "Qwen3-TTS 0.6B" : "Qwen3-TTS 1.7B"),
    hosted: false,
  };
}

// The next step after a fix failed with this code, or undefined when there is none to offer:
// `consent` asks the person in the card first (a fresh click), `message` and `label` name the
// notice and its button. A saved voice the plan refuses asks consent for a one-off copy; a hosted
// model the plan refuses offers a model on this computer (consent first if none was given yet).
function fixRetry(code, payload, text = "", voice = {}) {
  if (code === "CONSENT_REQUIRED")
    return {
      consent: true,
      label: voice.hosted ? "Make the fix" : "Make it on this computer",
      // A saved voice's fix named no model: consent is for the copy's, which the card shows.
      payload: {
        ...payload,
        voice: "local",
        consent: true,
        ...(voice.voiceModel ? { voiceModel: voice.voiceModel } : {}),
      },
    };
  if (code === "PLAN_REQUIRED")
    return {
      consent: !voice.localConsent,
      local: true,
      // The refusal says which wall it was (plan, seat or credits) and what to do about it.
      message:
        text ||
        "Hosted voice fixes are on paid plans. Make this one on this computer instead, or upgrade in Settings, Plan & billing.",
      label: "Use on this computer",
      payload: {
        ...payload,
        voice: "local",
        voiceModel: LOCAL_VOICE,
        ...(voice.localConsent ? {} : { consent: true }),
      },
    };
  const messages = {
    LOCAL_VOICE_INSTALL_FAILED: ["The voice couldn't be set up on this computer.", "Retry"],
    HOSTED_VOICE_FAILED: ["The hosted voice couldn't make the fix.", "Retry"],
    VOICE_CHECK_INSTALL_FAILED: ["The word check couldn't be set up.", "Retry"],
    LOCAL_VOICE_BUSY: ["Another voice fix is still running.", "Try again"],
    CONSENT_RECORDED_FIX_FAILED: ["Your consent is saved, but the fix didn't work.", "Try again"],
  };
  if (!messages[code]) return undefined;
  return {
    consent: false,
    message: `${messages[code][0]} ${text}`.trim(),
    label: messages[code][1],
    payload,
  };
}

// Which history step a key press asks for: Cmd/Ctrl+Z undo, Shift+Cmd/Ctrl+Z and (Windows,
// Linux) Ctrl+Y redo; undefined for anything else, a key repeat, or a key typed into a field.
function historyKey(event) {
  // A held key repeats: one press is one step.
  if (!(event.metaKey || event.ctrlKey) || event.altKey || event.repeat) return undefined;
  if (event.target?.closest?.("input, textarea")) return undefined;
  const key = event.key.toLowerCase();
  if (key === "z") return event.shiftKey ? "redo" : "undo";
  return key === "y" && !event.metaKey ? "redo" : undefined;
}

// What the card says after a fix.
function fixDone() {
  return "Fixed. Click the new words to hear them.";
}

// Said once, after the first hosted fix for this profile (`hostedNote`, set once per user by the
// host), in the notice area so the next status line doesn't wipe it.
const HOSTED_HINT =
  "Voice fixes can also run on this computer: Settings → Creative preferences → Voice fixes.";

// Each fix as one run: its id and audio, where its words start and end in the source and how
// long they were spoken.
function fixRuns(model) {
  const runs = new Map();
  model.words.forEach((word) => {
    if (word.state !== "replaced" || !word.replacement) return;
    const run = runs.get(word.replacement.id);
    if (run) run.endS = word.endS;
    else
      runs.set(word.replacement.id, {
        id: word.replacement.id,
        audio: word.replacement.audio,
        startS: word.startS,
        endS: word.endS,
        ...(typeof word.replacement.durationS === "number"
          ? { durationS: word.replacement.durationS }
          : {}),
      });
  });
  return [...runs.values()].map((run) => ({ ...run, spokenS: run.endS - run.startS }));
}

function sourceDuration(model) {
  return model.duration?.sourceS ?? model.media?.[0]?.durationS ?? model.words.at(-1)?.endS ?? 0;
}

// The card's edits: the last authoritative model the server returned plus the edits still in
// flight, shown on top of it in the order they were made. Settling an edit only ever moves the
// committed model forward (never to an older revision), so an earlier edit failing after a later
// one succeeded can't put the older card back.
function editQueue(initial) {
  let committed = initial;
  let next = 0;
  const inFlight = new Map();
  return {
    get committed() {
      return committed;
    },
    get pending() {
      return inFlight.size;
    },
    begin(apply) {
      const id = ++next;
      inFlight.set(id, apply);
      return id;
    },
    // A newer (or same-revision, e.g. a finished preview) authoritative card replaces the old one.
    commit(card) {
      if (!card || !Array.isArray(card.words) || (card.rev ?? 0) < (committed.rev ?? 0))
        return false;
      committed = card;
      return true;
    },
    settle(id, card) {
      inFlight.delete(id);
      return this.commit(card);
    },
    view() {
      return [...inFlight.values()].reduce((model, apply) => {
        if (!apply) return model;
        const draft = {
          ...model,
          words: [...model.words],
          takes: model.takes ? [...model.takes] : model.takes,
        };
        apply(draft);
        return draft;
      }, committed);
    },
  };
}

// The removed words a Clean up would act on, counted the way the card shows them.
function cleanupCounts(model, spansNow = cutSpans(model)) {
  const maxS = (model.pauses?.maxMs ?? 700) / 1000;
  const playing = model.words.filter((word) => audible(word) && word.kind !== "punct");
  const fillers = model.words.filter((word) => word.kind === "filler" && audible(word)).length;
  const pauses = playing
    .slice(1)
    .filter(
      (word, index) =>
        editedTime(spansNow, word.startS) - editedTime(spansNow, playing[index].endS) > maxS + 0.05,
    ).length;
  const retakes = (model.takes ?? []).length;
  return { fillers, pauses, retakes };
}

// What Restore brings back for one struck word: the whole cut it is in, the run of removed words
// around it with the same reason.
function cutRun(words, at) {
  const reason = words[at]?.reason;
  const same = (index) => words[index]?.state === "removed" && words[index].reason === reason;
  if (!same(at)) return [];
  let first = at;
  let last = at;
  while (same(first - 1)) first--;
  while (same(last + 1)) last++;
  return Array.from({ length: last - first + 1 }, (_, offset) => first + offset);
}

// Codes of the warnings about a cut's edges, worth listening across.
const LISTEN = new Set(["tight_cut", "filler_edge_uncertain"]);

// The warnings of an edit (`changed.warnings`) the card shows: a fix whose new voice may say other
// words, with the fix it is about, and cuts to listen across, with the word each is at (a word id
// in the message, else its "at 1.23s" source time). Notes about saving or the preview stay with
// the status line and the agent.
function editWarnings(model, warnings) {
  const list = (Array.isArray(warnings) ? warnings : []).filter(
    (warning) => typeof warning?.message === "string",
  );
  const index = new Map(model.words.map((word, at) => [word.id, at]));
  return {
    voice: list
      .filter((warning) => warning.code === "voice_words_mismatch")
      .map((warning) => ({
        message: warning.message.replace(/;[^;]*$/, "."),
        replacement: model.words.find((word) =>
          word.replacement?.warnings?.some((entry) => entry.message === warning.message),
        )?.replacement.id,
      })),
    listen: list
      .filter((warning) => LISTEN.has(warning.code))
      .flatMap((warning) => {
        const id = /\b(w\d+)\b/.exec(warning.message)?.[1];
        const seconds = /\bat (\d+(?:\.\d+)?)s\b/.exec(warning.message)?.[1];
        const at = index.has(id)
          ? index.get(id)
          : seconds === undefined
            ? -1
            : wordAt(model.words, Number(seconds) + 0.005);
        return at >= 0 ? [{ at, message: warning.message }] : [];
      }),
  };
}

function clock(seconds) {
  const whole = Math.max(0, Math.round(seconds));
  const hours = Math.floor(whole / 3600);
  const minutes = Math.floor((whole % 3600) / 60);
  const rest = String(whole % 60).padStart(2, "0");
  return hours ? `${hours}:${String(minutes).padStart(2, "0")}:${rest}` : `${minutes}:${rest}`;
}

globalThis.transcriptModel = {
  audible,
  cutSpans,
  editedTime,
  sourceTime,
  cutAt,
  editedDuration,
  wordAt,
  paragraphs,
  ranges,
  rangeRef,
  fixRange,
  withBase,
  settleReceipt,
  fixing,
  previewTimeline,
  previewTime,
  previewSource,
  playablePreview,
  previewCurrent,
  previewWords,
  previewWordAt,
  previewSeek,
  fixVoice,
  fixRetry,
  HOSTED_HINT,
  fixDone,
  historyKey,
  fixRuns,
  editQueue,
  cleanupCounts,
  cutRun,
  editWarnings,
  clock,
};

// The card's player: one video element, playing either a rendered preview ("preview", exact fix
// timing and held picture; while a newer one renders, the last finished one with its own word
// times) or, when no preview has finished, the recording with the edit's cuts skipped ("source").
// Fixed-word audio in source mode has one controller that follows the video's transport.
globalThis.transcriptPlayer = (host, ui, view, say) => {
  const {
    audible,
    editedTime,
    sourceTime,
    cutAt,
    editedDuration,
    wordAt,
    fixRuns,
    playablePreview,
    previewCurrent,
    previewWordAt,
    previewSeek,
  } = globalThis.transcriptModel;
  let mode = "source";
  let mediaUrl;
  // The loaded preview's word times, kept with the file: a newer revision's model must not move
  // the playhead of an older preview still playing.
  let entries;
  // Loads resolve out of order: only the newest may change the file, and only the load that set
  // the file may restore its position when its metadata arrives.
  const loads = { latest: 0, shown: 0 };
  const fix = { id: undefined, audio: undefined, token: 0 };
  let runs = { model: undefined, list: [] };
  // Pausing, seeking, ending or changing speed stops the fixed-word sound; follow() restarts it
  // at the right point when playback is inside a fix again.
  ["pause", "seeking", "ended", "emptied"].forEach((type) =>
    ui.video.addEventListener(type, () => stopFixAudio()),
  );
  ui.video.addEventListener("ratechange", () => {
    if (fix.audio) fix.audio.playbackRate = ui.video.playbackRate;
  });

  // The path of the preview to play (this revision's, or the last finished one while a newer
  // renders), else undefined.
  function playable(card) {
    return playablePreview(card)?.path;
  }

  // Prefers a finished preview (exact fix timing and held picture), saying it is updating while a
  // newer one renders; with none finished, plays the source with skips. Switching keeps the word
  // being heard (edited times differ between revisions) and whether it was playing.
  async function loadMedia() {
    const load = ++loads.latest;
    // The file and its word times come from the same model, before any await.
    const current = view();
    const model = current.model;
    const preview = playable(model);
    const source = model.media?.[0]?.path;
    const resolve = (path) =>
      path ? host.assets.resolve({ path }).catch(() => undefined) : Promise.resolve(undefined);
    const rendered = await resolve(preview);
    const resolved = rendered ?? (await resolve(source));
    if (load !== loads.latest) return;
    const next = rendered ? "preview" : "source";
    // A failed render isn't updating: the card offers Retry instead.
    ui.updating.hidden =
      !resolved ||
      !model.preview ||
      model.preview.failed === true ||
      (next === "preview" && previewCurrent(model));
    const audioOnly = Boolean(resolved) && !(resolved.mimeType ?? "video/").startsWith("video/");
    ui.noMedia.hidden = Boolean(resolved);
    ui.video.hidden = !resolved || audioOnly;
    ui.audio.hidden = !audioOnly;
    ui.screen.classList.toggle("audio", audioOnly);
    ui.audio.lastChild.textContent = source?.split(/[\\/]/).at(-1) ?? "";
    ui.play.disabled = !resolved;
    if (!resolved || (resolved.url === mediaUrl && next === mode)) {
      entries = current.mapping;
      return;
    }
    const at = currentEdited();
    const word = mediaUrl ? currentWord() : -1;
    const wasPlaying = !ui.video.paused;
    stopFixAudio();
    ui.video.muted = false;
    mode = next;
    mediaUrl = resolved.url;
    entries = current.mapping;
    loads.shown = load;
    ui.video.src = resolved.url;
    ui.video.addEventListener(
      "loadedmetadata",
      () => {
        if (load !== loads.shown) return;
        if (word >= 0) seekWord(word);
        else seekEdited(at);
        if (wasPlaying) void ui.video.play();
      },
      { once: true },
    );
  }

  // Position and length in the edited cut, whichever file is playing.
  function currentEdited() {
    const time = ui.video.currentTime || 0;
    return mode === "preview" ? time : editedTime(view().spans, time);
  }

  function totalEdited() {
    if (mode !== "preview") return editedDuration(view().model, view().spans);
    if (Number.isFinite(ui.video.duration)) return ui.video.duration;
    return previewCurrent(view().model) && typeof view().model.duration?.editedS === "number"
      ? view().model.duration.editedS
      : (entries?.at(-1)?.endS ?? 0);
  }

  // The index of the word being heard, for the transcript's playhead, or -1.
  function currentWord() {
    const time = ui.video.currentTime || 0;
    if (mode === "preview") return entries ? previewWordAt(entries, time) : -1;
    return wordAt(view().model.words, time);
  }

  function togglePlay() {
    if (ui.play.disabled) return;
    if (ui.video.paused) {
      const cut = mode === "source" && cutAt(view().spans, ui.video.currentTime);
      if (cut) ui.video.currentTime = cut[1];
      void ui.video.play();
    } else ui.video.pause();
  }

  function seekWord(at) {
    const word = view().model.words[at];
    if (!word) return;
    if (mode === "preview") {
      if (entries) ui.video.currentTime = previewSeek(entries, at);
      return;
    }
    ui.video.currentTime = audible(word)
      ? word.startS
      : (cutAt(view().spans, word.startS)?.[1] ?? word.startS);
  }

  function seekEdited(editedS) {
    const clamped = Math.max(0, Math.min(totalEdited(), editedS));
    ui.video.currentTime = mode === "preview" ? clamped : sourceTime(view().spans, clamped);
  }

  function seekTrack(event) {
    const rect = ui.track.getBoundingClientRect();
    const fraction = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width));
    seekEdited(fraction * totalEdited());
  }

  // Starts a fix's sound where playback is within its words; a newer start, pause or seek made
  // while its file resolves cancels it.
  async function playFixAudio(run) {
    stopFixAudio();
    const token = fix.token;
    fix.id = run.id;
    const resolved = await host.assets.resolve({ path: run.audio }).catch(() => undefined);
    if (!resolved || token !== fix.token || ui.video.paused) return;
    const audio = new Audio(resolved.url);
    audio.playbackRate = ui.video.playbackRate;
    audio.currentTime = Math.max(0, ui.video.currentTime - run.startS);
    fix.audio = audio;
    void audio.play();
  }

  function stopFixAudio() {
    fix.token++;
    fix.audio?.pause();
    fix.audio = undefined;
    fix.id = undefined;
  }

  // Plays just the new words, through the same controller, so pressing Play afterwards stops it.
  async function hear(word) {
    const audio = word.replacement?.audio;
    if (!audio) return say("The new words are still being made.");
    ui.video.pause();
    stopFixAudio();
    const token = fix.token;
    const resolved = await host.assets
      .resolve({ path: audio })
      .catch((error) => say(error instanceof Error ? error.message : String(error)));
    if (!resolved || token !== fix.token) return;
    fix.id = "hear";
    fix.audio = new Audio(resolved.url);
    void fix.audio.play();
  }

  // Each frame while playing from the recording: skip cuts, and play a fix's new audio over its
  // words (the recording muted) until playback leaves them.
  function follow() {
    const video = ui.video;
    if (video.paused || mode !== "source") return;
    const cut = cutAt(view().spans, video.currentTime);
    if (cut) video.currentTime = cut[1];
    // The whole span of a fix counts, pauses between its words included.
    const model = view().model;
    if (runs.model !== model) runs = { model, list: fixRuns(model).filter((run) => run.audio) };
    const time = video.currentTime;
    const run = runs.list.find((entry) => time >= entry.startS && time < entry.endS);
    const fixing = Boolean(run);
    video.muted = fixing;
    if (run && fix.id !== run.id) void playFixAudio(run);
    if (!fixing && fix.id) stopFixAudio();
  }

  return {
    playable,
    loadMedia,
    currentEdited,
    totalEdited,
    currentWord,
    togglePlay,
    seekWord,
    seekEdited,
    seekTrack,
    follow,
    hear,
  };
};

// The card's DOM helpers and icons, kept apart so each card file stays small.
function el(tag, attributes = {}, ...children) {
  const node = document.createElement(tag);
  Object.entries(attributes).forEach(([name, value]) => node.setAttribute(name, value));
  node.append(...children.filter((child) => child !== "" && child !== undefined && child !== null));
  return node;
}

function svg(path, size = 14) {
  const node = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  node.setAttribute("viewBox", "0 0 24 24");
  node.setAttribute("width", String(size));
  node.setAttribute("height", String(size));
  node.setAttribute("fill", "none");
  node.setAttribute("stroke", "currentColor");
  node.setAttribute("stroke-width", "2");
  node.setAttribute("stroke-linecap", "round");
  node.setAttribute("stroke-linejoin", "round");
  node.setAttribute("aria-hidden", "true");
  node.innerHTML = path;
  return node;
}

function playIcon() {
  return svg('<path d="M7 4v16l13-8z" fill="currentColor"/>', 16);
}
function pauseIcon() {
  return svg('<path d="M6 5h4v14H6zM14 5h4v14h-4z" fill="currentColor" stroke="none"/>', 16);
}
function caretIcon() {
  return svg('<path d="M6 9l6 6 6-6"/>', 12);
}
function undoIcon() {
  return svg('<path d="M9 14l-4-4 4-4"/><path d="M5 10h11a4 4 0 0 1 0 8h-1"/>');
}
function redoIcon() {
  return svg('<path d="M15 14l4-4-4-4"/><path d="M19 10H8a4 4 0 0 0 0 8h1"/>');
}
// Undo and Redo in the toolbar; `step` runs "undo" or "redo".
function historyTools(ui, step) {
  // Narrow cards show only the icons (index.css); the label stays the button's name.
  const tool = (label) => ({
    type: "button",
    class: "tool history",
    "aria-label": label,
    title: label,
  });
  ui.undo = el("button", tool("Undo"), undoIcon(), el("span", {}, "Undo"));
  ui.redo = el("button", tool("Redo"), redoIcon(), el("span", {}, "Redo"));
  ui.undo.addEventListener("click", () => step("undo"));
  ui.redo.addEventListener("click", () => step("redo"));
}
function voiceIcon() {
  return svg(
    '<path d="M9 2a3 3 0 0 0-3 3v5a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z"/><path d="M5 10a4 4 0 0 0 8 0M9 14v4"/><path d="M15 8l2 2 4-4"/>',
  );
}

// One compact row per retake group: which take is kept, and a chip to keep another.
function takeBar(take) {
  return el(
    "span",
    { class: "takes", contenteditable: "false", "data-take": take.id },
    el("span", { class: "takes-label" }, `${take.ranges.length} takes`),
    ...take.ranges.map((_range, number) =>
      el(
        "button",
        {
          type: "button",
          class: "take",
          "data-take": take.id,
          "data-keep": String(number),
          "aria-pressed": String(number === take.keep),
          title: number === take.keep ? "The take you are keeping" : "Keep this take instead",
        },
        `Take ${number + 1}`,
      ),
    ),
  );
}

// A suggested retake (found, not cut): offered with Accept and Dismiss, nothing struck through.
function suggestionBar(take) {
  return el(
    "span",
    { class: "takes suggested", contenteditable: "false", "data-take": take.id },
    el(
      "span",
      { class: "takes-label" },
      `Said ${take.ranges.length} times. Keep take ${take.keep + 1}?`,
    ),
    el(
      "button",
      {
        type: "button",
        class: "take accept",
        "data-take": take.id,
        "data-keep": String(take.keep),
      },
      "Accept",
    ),
    el("button", { type: "button", class: "take dismiss", "data-take": take.id }, "Dismiss"),
  );
}

/** A card button whose click stays inside the card. */
function button(label, onClick, kind = "") {
  const node = el("button", { type: "button", class: kind }, label);
  node.addEventListener("click", (event) => {
    event.stopPropagation();
    onClick();
  });
  return node;
}

/**
 * Ask once for voice consent in the card's notice area; the button waits for the tick. The box and
 * the button are a fresh click of the person's own, which the host needs before it sends consent.
 */
function consentNotice(area, text, onAgree, label = "Make it on this computer") {
  const box = el("input", { type: "checkbox" });
  const agree = button(label, () => {
    area.hidden = true;
    area.replaceChildren();
    onAgree();
  });
  agree.disabled = true;
  box.addEventListener("change", () => {
    agree.disabled = !box.checked;
  });
  area.hidden = false;
  area.replaceChildren(
    el("span", {}, text),
    el(
      "label",
      { class: "consent" },
      box,
      el("span", {}, "This is my voice, or I have the right to use it"),
    ),
    agree,
  );
}

/**
 * The Fix in my voice bubble: the new words, which voice makes them, the consent tick when that
 * voice needs one, and, once a voice was agreed to for this project, a way to forget it (consent
 * withdrawn and the saved voice files deleted). `apply` gets the typed words.
 */
function fixBubble(original, voice, actions) {
  const input = el("input", {
    type: "text",
    class: "fix-input",
    value: original,
    "aria-label": "New words",
  });
  const consent = el("input", { type: "checkbox" });
  const apply = el("button", { type: "button", class: "primary" }, "Fix");
  const sync = () => {
    const text = input.value.trim();
    apply.disabled = !text || text === original || (voice.needsConsent && !consent.checked);
  };
  input.addEventListener("input", sync);
  consent.addEventListener("change", sync);
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !apply.disabled) apply.click();
    if (event.key === "Escape") actions.cancel();
  });
  apply.addEventListener("click", () => actions.apply(input.value.trim()));
  sync();
  return {
    input,
    node: el(
      "div",
      { class: "fix" },
      input,
      el("p", { class: "voice" }, voice.text),
      voice.needsConsent
        ? el(
            "label",
            { class: "consent" },
            consent,
            el("span", {}, "This is my voice, or I have the right to use it"),
          )
        : "",
      el(
        "div",
        { class: "row" },
        voice.forgettable ? button("Forget my saved voice", actions.forget) : "",
        button("Cancel", actions.cancel),
        apply,
      ),
    ),
  };
}

/** The playhead slider's values for assistive technology, in seconds of the edited cut. */
function trackValues(track, now, total, label) {
  track.setAttribute("aria-valuemin", "0");
  track.setAttribute("aria-valuemax", String(Math.round(total)));
  track.setAttribute("aria-valuenow", String(Math.round(now)));
  track.setAttribute("aria-valuetext", label);
}

/**
 * What a key press in the transcript will act on, for screen readers: the selected words, said in
 * a polite live region of its own so the visible status line keeps its message.
 */
function announceSelection(region, words) {
  const text = words.map((word) => word.text).join(" ");
  region.textContent = text
    ? `Selected: ${text.length > 120 ? `${text.slice(0, 120)}…` : text}`
    : "";
}

/** Scroll the transcript only when the playing word leaves its middle band. */
function keepInView(pane, node) {
  const box = pane.getBoundingClientRect();
  const rect = node.getBoundingClientRect();
  if (rect.top < box.top + 24 || rect.bottom > box.bottom - 24)
    pane.scrollBy({ top: rect.top - box.top - box.height / 3, behavior: "smooth" });
}

/** The Clean up menu: each kind with its count, ticked when there is any, and one Clean up. */
function cleanupMenu(ui, clean) {
  let open = false;
  const toggle = (next = !open) => {
    open = next;
    ui.menu.hidden = !open;
    ui.clean.setAttribute("aria-expanded", String(open));
    if (!open) return;
    const counts = ui.menuCounts;
    const checks = [
      ["fillers", "Filler words", counts.fillers],
      ["pauses", "Long pauses", counts.pauses],
      // Retakes are found when cleaning, so the option stays available; a count shows groups found.
      ["retakes", "Retakes", counts.retakes || undefined],
    ].map(([key, label, count]) => {
      const box = el("input", { type: "checkbox", name: key });
      box.checked = count !== 0;
      box.disabled = count === 0;
      return [
        key,
        box,
        el(
          "label",
          { class: "option" },
          box,
          el("span", {}, label),
          el("span", { class: "count" }, count === undefined ? "" : String(count)),
        ),
      ];
    });
    const apply = button(
      "Clean up",
      () => {
        const chosen = Object.fromEntries(checks.map(([key, box]) => [key, box.checked]));
        if (!Object.values(chosen).some(Boolean)) return;
        toggle(false);
        clean(chosen);
      },
      "primary",
    );
    ui.menu.replaceChildren(...checks.map(([, , label]) => label), apply);
  };
  ui.clean.addEventListener("click", () => toggle());
  document.addEventListener("pointerdown", (event) => {
    if (open && !event.target.closest(".menu-anchor")) toggle(false);
  });
}

/**
 * The warnings that need the user, in the toolbar: a fix whose new voice may say other words
 * (Hear it, Try again), and a quiet count of cuts to listen across; each click plays the next.
 */
function warningArea(actions) {
  const voice = el("div", { class: "notice warn", role: "status", hidden: "" });
  const listen = el("button", { type: "button", class: "listen", hidden: "" });
  let cuts = [];
  const count = () => {
    listen.hidden = !cuts.length;
    listen.textContent = `${cuts.length} cut${cuts.length === 1 ? "" : "s"} to listen to`;
    listen.title = cuts[0]?.message ?? "";
  };
  listen.addEventListener("click", () => {
    const next = cuts.shift();
    count();
    if (next) actions.jump(next.at);
  });
  return {
    voice,
    listen,
    show(found) {
      cuts = [...cuts, ...found.listen].filter(
        (cut, index, list) => list.findIndex((other) => other.at === cut.at) === index,
      );
      count();
      const fix = found.voice.at(-1);
      if (!fix) return;
      const word = fix.replacement && actions.fix(fix.replacement);
      voice.replaceChildren(
        el("span", {}, fix.message),
        ...(word
          ? [
              button("Hear it", () => actions.hear(word)),
              button("Try again", () => actions.retry(word)),
            ]
          : []),
        button("Dismiss", () => {
          voice.hidden = true;
        }),
      );
      voice.hidden = false;
    },
  };
}

/**
 * "Preview failed · Retry" over the player, for a preview whose render failed (`preview.failed`):
 * the card keeps playing the recording with skips, and Retry renders it again. `show(model)`
 * follows the card; a failed preview is not "Updating".
 */
function previewFailure(ui, retry) {
  const node = el(
    "div",
    { class: "preview-failed", role: "status", hidden: "" },
    el("span", {}, "Preview failed"),
    button("Retry", retry),
  );
  return {
    node,
    show(model) {
      const failed = model.preview?.failed === true;
      node.hidden = !failed;
      node.title = failed ? String(model.preview.error ?? "") : "";
      if (failed) ui.updating.hidden = true;
    },
  };
}

globalThis.transcriptUi = {
  previewFailure,
  el,
  button,
  consentNotice,
  fixBubble,
  trackValues,
  announceSelection,
  keepInView,
  svg,
  playIcon,
  pauseIcon,
  caretIcon,
  undoIcon,
  historyTools,
  voiceIcon,
  takeBar,
  suggestionBar,
  cleanupMenu,
  warningArea,
};

# Drafts in HTML widgets

Catalog specs save `$bindState` values as drafts by themselves. In HTML, keep the user's unsent typing in a managed draft so it survives reloads, placement changes and `edit_widget`:

<!-- prettier-ignore -->
```js
const draft = host.drafts.createAutosave();
await draft.ready;
input.value = draft.getSnapshot().value.note ?? "";
input.oninput = () => void draft.stage({ note: input.value }).catch(() => {});
```

- `stage(patch)` takes a JSON merge patch (objects merge, arrays replace, `null` deletes) and saves in the background. `getSnapshot()` is `{status, revision, value, error?}` with status `loading`, `pending`, `saving`, `saved` or `error`; `subscribe(callback)` follows it. Only `saved` means the host has it.
- On a conflict offer the user the choice: "Keep my edits" calls `retry({overwriteConflicts:true})`, "Discard" calls `discard()`. Never pick for them.
- Drafts never submit anything. Send a decision from the click handler itself, with its current payload; do not wait for a draft save first.
- Live data belongs in bindings, not drafts. On teardown, unsubscribe and call `draft.dispose()`; pending edits are kept by the host.
